window.CASE_BANK=[{"id":"dp-sunroof","title":"Sun Roof — Offre, acceptation et information","subject":"Droit des obligations","topic":"Formation du contrat","provider":"Objectif Barreau","year":2026,"source":{"label":"Objectif Barreau — Préparation estivale CRFPA 2026, corrigé sujet n°1","pages":"corrigé p. 1–3","kind":"correction-2026"},"scenario":"Amélie négocie l'installation de panneaux photovoltaïques. Sun Roof lui adresse une proposition complète avec une remise exceptionnelle de 20 % valable jusqu'au 1er juin. Elle signe et renvoie les documents : ils parviennent à Sun Roof le 1er juin, mais ne sont lus que le 2. Après l'installation, un débat naît sur le prix et sur l'origine non européenne des panneaux, que la cliente relie à un projet de label environnemental qu'elle n'avait pas expliqué au prestataire.","questions":[{"id":"dp-sun-01","phase":"Qualification","type":"single","stem":"La proposition chiffrée de Sun Roof, qui décrit les prestations, le prix et prévoit un bon à signer pour accord définitif, doit principalement être qualifiée de…","options":["simple publicité","offre de contracter","pacte de préférence","promesse unilatérale"],"answers":[1],"explanation":"Le corrigé la traite comme une offre : elle contient les éléments essentiels du contrat et exprime une volonté de s'engager en cas d'acceptation.","reasoning":"Identifier d'abord si la proposition est ferme et précise.","legalRefs":["C. civ., art. 1113 et 1114"],"verified":null,"source":{"label":"Objectif Barreau — Préparation estivale CRFPA 2026, corrigé sujet n°1 — corrigé p. 1–3","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-sunroof"}},{"id":"dp-sun-02","phase":"Règle","type":"single","stem":"L'offre prévoit une remise de 20 % valable jusqu'au 1er juin. L'acceptation est reçue par Sun Roof le 1er juin mais n'est lue que le 2 juin. À quelle date le contrat est-il formé ?","options":["30 mai, date d'envoi","1er juin, date de réception","2 juin, date de lecture","à la date de la première facture"],"answers":[1],"explanation":"L'article 1121 consacre la théorie de la réception : le contrat est conclu dès que l'acceptation parvient à l'offrant. La prise de connaissance effective n'est pas exigée.","reasoning":"Distinguer émission, réception et connaissance effective.","legalRefs":["C. civ., art. 1121"],"verified":{"status":"officiel","label":"Légifrance, art. 1121, vérifié juillet 2026","url":"https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000032040856/"},"source":{"label":"Objectif Barreau — Préparation estivale CRFPA 2026, corrigé sujet n°1 — corrigé p. 1–3","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-sunroof"}},{"id":"dp-sun-03","phase":"Application","type":"single","stem":"Quelle conséquence tirer de la réception de l'acceptation le 1er juin ?","options":["La remise est perdue car Sun Roof n'a lu le courrier que le 2 juin","Le contrat est conclu aux conditions incluant la remise de 20 %","Le contrat n'est pas formé faute de signature électronique","Sun Roof peut choisir librement le prix après réception"],"answers":[1],"explanation":"Puisque l'acceptation est parvenue avant l'expiration de l'offre tarifaire, le contrat s'est formé avec la remise de 20 %.","reasoning":"Appliquer la date de formation au contenu de l'offre encore en vigueur.","legalRefs":["C. civ., art. 1121 et 1103"],"verified":null,"source":{"label":"Objectif Barreau — Préparation estivale CRFPA 2026, corrigé sujet n°1 — corrigé p. 1–3","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-sunroof"}},{"id":"dp-sun-04","phase":"Conclusion","type":"single","stem":"Sun Roof peut-elle facturer un prix supérieur en écartant unilatéralement la remise ?","options":["Oui, parce que la remise était exceptionnelle","Oui, si la facture est émise après le 1er juin","Non, le contrat formé oblige les parties aux conditions convenues","Non, mais uniquement si Amélie est consommatrice"],"answers":[2],"explanation":"Le contrat légalement formé tient lieu de loi aux parties. La remise incorporée au contrat ne peut être retirée unilatéralement.","reasoning":"Une fois le contrat formé, passer du droit de la formation à la force obligatoire.","legalRefs":["C. civ., art. 1103"],"verified":null,"source":{"label":"Objectif Barreau — Préparation estivale CRFPA 2026, corrigé sujet n°1 — corrigé p. 1–3","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-sunroof"}},{"id":"dp-sun-05","phase":"Repérage","type":"multiple","stem":"Concernant l'origine non européenne des panneaux, quelles conditions sont centrales pour déclencher le devoir précontractuel d'information de droit commun ?","options":["Le débiteur doit connaître l'information","L'information doit être déterminante pour le consentement","L'information doit avoir un lien direct et nécessaire avec le contenu du contrat ou la qualité des parties","Toute information utile, même secondaire, doit être transmise"],"answers":[0,1,2],"explanation":"Le corrigé retient les critères de l'article 1112-1 : connaissance de l'information, caractère déterminant et lien direct et nécessaire. Il n'existe pas de devoir général de révéler toute information utile.","reasoning":"Tester successivement les conditions du devoir d'information.","legalRefs":["C. civ., art. 1112-1"],"verified":null,"source":{"label":"Objectif Barreau — Préparation estivale CRFPA 2026, corrigé sujet n°1 — corrigé p. 1–3","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-sunroof"}},{"id":"dp-sun-06","phase":"Application","type":"single","stem":"Amélie voulait ultérieurement obtenir un label « Eco Plus », mais elle n'avait pas expliqué ce projet à Sun Roof. Le corrigé estime que le manquement au devoir d'information sur la provenance des panneaux est…","options":["certain, car un professionnel doit révéler tout ce qu'il sait","difficile à caractériser, faute notamment d'éléments établissant le caractère déterminant et nécessaire de cette provenance","automatiquement constitutif d'un dol","sans importance car l'article 1112-1 ne s'applique jamais entre professionnels"],"answers":[1],"explanation":"Le corrigé souligne que la provenance pouvait être connue du professionnel, mais que le caractère déterminant et le lien direct et nécessaire ne ressortent pas suffisamment des faits, notamment puisque le projet de label n'avait pas été porté à sa connaissance.","reasoning":"Ne pas confondre information connue par le professionnel et information juridiquement due.","legalRefs":["C. civ., art. 1112-1"],"verified":null,"source":{"label":"Objectif Barreau — Préparation estivale CRFPA 2026, corrigé sujet n°1 — corrigé p. 1–3","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-sunroof"}},{"id":"dp-sun-07","phase":"Conclusion","type":"single","stem":"Sur les seuls faits du dossier, une nullité pour dol liée à l'origine des panneaux paraît-t-elle acquise ?","options":["Oui, nécessairement","Non : l'intention de tromper et le caractère déterminant ne sont pas suffisamment établis","Oui, car tout défaut d'information constitue un dol","Oui, dès qu'une qualité environnementale est en cause"],"answers":[1],"explanation":"Le dol suppose notamment une tromperie intentionnelle provoquant une erreur déterminante. Le corrigé ne considère pas ces éléments comme suffisamment établis ici.","reasoning":"Pour passer du devoir d'information au dol, ajouter l'élément intentionnel et le caractère déterminant.","legalRefs":["C. civ., art. 1130, 1137"],"verified":null,"source":{"label":"Objectif Barreau — Préparation estivale CRFPA 2026, corrigé sujet n°1 — corrigé p. 1–3","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-sunroof"}}],"tags":["offre","acceptation","devoir d'information","dol"],"warning":null},{"id":"dp-greensol","title":"Green Sol — Pourparlers, rupture et confidentialité","subject":"Droit des obligations","topic":"Négociations précontractuelles","provider":"Objectif Barreau","year":2026,"source":{"label":"Objectif Barreau — Préparation estivale CRFPA 2026, corrigé sujet n°1","pages":"corrigé p. 4–7","kind":"correction-2026"},"scenario":"Avant de choisir Sun Roof, Amélie avait mené des négociations avancées avec Green Sol. Elle avait reçu une proposition complète et répondu qu'elle correspondait à ses attentes, tout en indiquant qu'elle répondrait plus tard. Elle a parallèlement poursuivi les discussions avec un concurrent et lui a communiqué certaines informations obtenues auprès de Green Sol. Green Sol considère qu'un contrat existait ou, à défaut, que le comportement d'Amélie était fautif.","questions":[{"id":"dp-green-01","phase":"Qualification","type":"single","stem":"Les documents complets envoyés par Green Sol après plusieurs échanges et visites doivent-ils nécessairement être écartés comme offre parce qu'ils n'ont pas encore été signés par Amélie ?","options":["Oui, un contrat de prestation doit toujours être solennel","Non, le consensualisme permet qu'une proposition ferme et précise constitue une offre sans signature préalable du destinataire","Oui, car seul un acte authentique peut constituer une offre","Oui, si le prix est avantageux"],"answers":[1],"explanation":"Le corrigé rappelle le consensualisme : l'absence de signature du destinataire n'empêche pas qu'une proposition suffisamment ferme et précise soit une offre.","reasoning":"Séparer la qualification de l'offre de la preuve ou du formalisme du contrat.","legalRefs":["C. civ., art. 1113, 1114, 1172"],"verified":null,"source":{"label":"Objectif Barreau — Préparation estivale CRFPA 2026, corrigé sujet n°1 — corrigé p. 4–7","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-greensol"}},{"id":"dp-green-02","phase":"Application","type":"single","stem":"Amélie répond que la proposition « correspond à ses attentes » mais qu'elle répondra lorsqu'elle aura le temps. Cette réponse constitue-t-elle une acceptation ?","options":["Oui, car elle exprime sa satisfaction","Oui, car l'acceptation peut être tacite","Non, elle ne manifeste pas sans équivoque la volonté d'être immédiatement liée","Non, uniquement parce qu'elle est envoyée par e-mail"],"answers":[2],"explanation":"Une acceptation doit manifester la volonté d'être lié dans les termes de l'offre. Le message annonce précisément une réponse future : il n'emporte donc pas acceptation.","reasoning":"Chercher une volonté actuelle et non équivoque de contracter.","legalRefs":["C. civ., art. 1118"],"verified":null,"source":{"label":"Objectif Barreau — Préparation estivale CRFPA 2026, corrigé sujet n°1 — corrigé p. 4–7","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-greensol"}},{"id":"dp-green-03","phase":"Règle","type":"single","stem":"En droit commun, quelle règle gouverne le silence du destinataire d'une offre ?","options":["Le silence vaut toujours acceptation entre professionnels","Le silence ne vaut pas acceptation, sauf loi, usages, relations d'affaires ou circonstances particulières","Le silence vaut acceptation après huit jours","Le silence vaut acceptation dès qu'une offre est avantageuse"],"answers":[1],"explanation":"La règle figure à l'article 1120 du Code civil. Le corrigé mentionne par erreur l'article 1122 sur ce point ; la V1.1 corrige cette référence après vérification de Légifrance.","reasoning":"Identifier la règle générale puis rechercher une exception.","legalRefs":["C. civ., art. 1120"],"verified":{"status":"officiel","label":"Légifrance, art. 1120, vérifié juillet 2026","url":"https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000032040861/"},"source":{"label":"Objectif Barreau — Préparation estivale CRFPA 2026, corrigé sujet n°1 — corrigé p. 4–7","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-greensol"}},{"id":"dp-green-04","phase":"Conclusion","type":"single","stem":"Un contrat Green Sol–Amélie est-il formé sur les faits décrits ?","options":["Oui","Non","Seulement si Green Sol a commencé à préparer le chantier","Seulement si les négociations ont duré plus d'un mois"],"answers":[1],"explanation":"Le corrigé conclut à l'absence d'acceptation et donc à l'absence de contrat.","reasoning":"La présence d'une offre ne suffit pas : vérifier la rencontre avec une acceptation.","legalRefs":["C. civ., art. 1113 et 1118"],"verified":null,"source":{"label":"Objectif Barreau — Préparation estivale CRFPA 2026, corrigé sujet n°1 — corrigé p. 4–7","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-greensol"}},{"id":"dp-green-05","phase":"Qualification","type":"single","stem":"Même sans contrat, le comportement d'Amélie pendant les pourparlers peut-il engager sa responsabilité ?","options":["Non, la liberté de rompre exclut toute faute","Oui, si le déroulement ou la rupture des négociations méconnaît la bonne foi","Seulement si une promesse unilatérale avait été signée","Uniquement si Green Sol prouve une fraude pénale"],"answers":[1],"explanation":"L'article 1112 maintient la liberté d'initiative, de conduite et de rupture, mais impose la bonne foi. Le corrigé retient comme potentiellement fautif le fait d'avoir laissé croire que la signature n'était plus qu'une formalité tout en négociant parallèlement avec un concurrent.","reasoning":"Après avoir exclu le contrat, envisager la responsabilité précontractuelle.","legalRefs":["C. civ., art. 1112"],"verified":null,"source":{"label":"Objectif Barreau — Préparation estivale CRFPA 2026, corrigé sujet n°1 — corrigé p. 4–7","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-greensol"}},{"id":"dp-green-06","phase":"Règle","type":"single","stem":"En cas de faute dans les négociations, quels préjudices sont exclus de la réparation par l'article 1112 ?","options":["Les frais inutilement exposés","Le bénéfice attendu du contrat non conclu et la perte de chance d'obtenir ces avantages","Tout préjudice moral","Les frais de déplacement"],"answers":[1],"explanation":"La réparation ne peut avoir pour objet de compenser les avantages attendus du contrat non conclu, ni la perte de chance d'obtenir ces avantages. Les dépenses de confiance peuvent, en revanche, être discutées si elles sont prouvées.","reasoning":"Distinguer l'intérêt positif du contrat non conclu de l'intérêt négatif lié aux pourparlers.","legalRefs":["C. civ., art. 1112"],"verified":null,"source":{"label":"Objectif Barreau — Préparation estivale CRFPA 2026, corrigé sujet n°1 — corrigé p. 4–7","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-greensol"}},{"id":"dp-green-07","phase":"Règle","type":"single","stem":"L'article 1112-2 crée-t-il une obligation générale de secret sur toutes les informations échangées pendant les négociations ?","options":["Oui","Non, il vise l'utilisation ou la divulgation non autorisée d'une information confidentielle obtenue pendant les négociations","Oui, mais seulement entre consommateurs","Non, il ne protège jamais les informations commerciales"],"answers":[1],"explanation":"Le texte protège les informations qui ont un caractère confidentiel ; il ne transforme pas tout échange précontractuel en secret général.","reasoning":"Qualifier d'abord l'information comme confidentielle.","legalRefs":["C. civ., art. 1112-2"],"verified":null,"source":{"label":"Objectif Barreau — Préparation estivale CRFPA 2026, corrigé sujet n°1 — corrigé p. 4–7","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-greensol"}},{"id":"dp-green-08","phase":"Application","type":"single","stem":"Amélie a transmis à Sun Roof des informations sur les techniques d'installation et une liste de clients de Green Sol, sans clause de confidentialité et sans autre précision sur leur caractère secret. Selon le corrigé, la responsabilité fondée sur l'article 1112-2 est…","options":["automatiquement acquise","difficile à retenir faute d'éléments suffisants établissant le caractère confidentiel","impossible car une clause écrite est toujours exigée","nécessairement pénale"],"answers":[1],"explanation":"Le corrigé ne nie pas qu'une confidentialité puisse exister sans clause, mais estime que les faits ne suffisent pas à établir le caractère confidentiel des informations transmises.","reasoning":"L'absence de clause n'est pas décisive ; la preuve du caractère confidentiel l'est.","legalRefs":["C. civ., art. 1112-2"],"verified":null,"source":{"label":"Objectif Barreau — Préparation estivale CRFPA 2026, corrigé sujet n°1 — corrigé p. 4–7","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-greensol"}}],"tags":["pourparlers","bonne foi","confidentialité"],"warning":null},{"id":"dp-capital","title":"Cession de capital — Offre ou négociation ?","subject":"Droit des obligations","topic":"Avant-contrats","provider":"Objectif Barreau","year":2026,"source":{"label":"Objectif Barreau — Préparation estivale CRFPA 2026, corrigé sujet n°1","pages":"corrigé p. 8–10","kind":"correction-2026"},"scenario":"Amélie envisage de céder une partie du capital de sa société. Elle adresse à Carla une proposition portant sur 10 % du capital, avec une date limite de réponse mais sans fixer de prix. Elle souhaite ensuite se retirer. Par ailleurs, elle avait auparavant consenti à Jean un droit de priorité sur une éventuelle cession de 30 % du capital. Il faut articuler qualification de la proposition, liberté des négociations et pacte de préférence.","questions":[{"id":"dp-capital-01","phase":"Qualification","type":"single","stem":"Amélie propose à Carla de lui céder 10 % du capital avant une date déterminée, mais sans fixer le prix ni son mode de détermination. Quelle qualification retient le corrigé ?","options":["Offre ferme de cession","Invitation à entrer en négociation","Promesse synallagmatique","Pacte de préférence"],"answers":[1],"explanation":"Faute de précision sur un élément essentiel de la cession, notamment le prix, la proposition ne vaut pas offre au sens de l'article 1114 ; elle ouvre des pourparlers.","reasoning":"Vérifier si les éléments essentiels permettent la formation du contrat par une simple acceptation.","legalRefs":["C. civ., art. 1114 ; art. 1583 par analogie sur les éléments de la vente"],"verified":null,"source":{"label":"Objectif Barreau — Préparation estivale CRFPA 2026, corrigé sujet n°1 — corrigé p. 8–10","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-capital"}},{"id":"dp-capital-02","phase":"Application","type":"single","stem":"Le fait que la proposition à Carla soit assortie d'une date limite suffit-il à la transformer en offre ferme ?","options":["Oui","Non","Oui, si le délai dépasse huit jours","Oui, si Carla est déjà associée"],"answers":[1],"explanation":"Un délai ne compense pas l'absence de précision sur un élément essentiel. La proposition reste une invitation à négocier.","reasoning":"Ne pas confondre durée d'une proposition et complétude de son contenu.","legalRefs":["C. civ., art. 1114"],"verified":null,"source":{"label":"Objectif Barreau — Préparation estivale CRFPA 2026, corrigé sujet n°1 — corrigé p. 8–10","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-capital"}},{"id":"dp-capital-03","phase":"Règle","type":"single","stem":"Amélie peut-elle, en principe, mettre fin à cette invitation à négocier avant la date indiquée ?","options":["Non, jamais","Oui, la rupture des pourparlers demeure libre sous réserve de la bonne foi","Seulement avec l'autorisation d'un juge","Seulement si Carla n'a pas répondu dans 24 heures"],"answers":[1],"explanation":"La liberté des négociations s'applique, même lorsqu'une date avait été évoquée, dès lors qu'il ne s'agit pas d'une offre ferme. Une faute de rupture reste toutefois possible selon les circonstances.","reasoning":"Une invitation à négocier relève du régime des pourparlers.","legalRefs":["C. civ., art. 1112"],"verified":null,"source":{"label":"Objectif Barreau — Préparation estivale CRFPA 2026, corrigé sujet n°1 — corrigé p. 8–10","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-capital"}},{"id":"dp-capital-04","phase":"Application","type":"single","stem":"Sur les faits du dossier, la rupture des discussions avec Carla est-elle qualifiée d'abusive par le corrigé ?","options":["Oui, nécessairement","Non, les éléments ne suffisent pas à caractériser une confiance légitime ou une rupture fautive","Oui, parce qu'une date limite avait été donnée","Oui, parce que toute négociation parallèle est interdite"],"answers":[1],"explanation":"Le corrigé ne relève pas d'éléments suffisants de brutalité tardive, de volonté de nuire ou de confiance légitime permettant de retenir une faute.","reasoning":"Appliquer les indices de faute à la chronologie concrète.","legalRefs":["C. civ., art. 1112"],"verified":null,"source":{"label":"Objectif Barreau — Préparation estivale CRFPA 2026, corrigé sujet n°1 — corrigé p. 8–10","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-capital"}},{"id":"dp-capital-05","phase":"Qualification","type":"single","stem":"L'accord par lequel Amélie s'engage à proposer prioritairement à Jean une cession de 30 % du capital si elle décide de vendre constitue…","options":["une offre","une promesse unilatérale","un pacte de préférence","une option d'achat légale"],"answers":[2],"explanation":"Le pacte de préférence oblige le promettant à proposer prioritairement le contrat au bénéficiaire s'il se décide à contracter.","reasoning":"Repérer une priorité, et non un engagement immédiat de conclure.","legalRefs":["C. civ., art. 1123"],"verified":null,"source":{"label":"Objectif Barreau — Préparation estivale CRFPA 2026, corrigé sujet n°1 — corrigé p. 8–10","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-capital"}},{"id":"dp-capital-06","phase":"Règle","type":"single","stem":"La validité d'un pacte de préférence exige-t-elle que le prix futur soit déjà déterminé ?","options":["Oui, toujours","Non, contrairement à la promesse unilatérale, les éléments essentiels du contrat futur n'ont pas tous à être arrêtés à ce stade","Oui, mais seulement pour les droits sociaux","Non, mais seulement si le pacte dure moins d'un an"],"answers":[1],"explanation":"Le corrigé rappelle que le pacte organise une priorité et ne forme pas le contrat futur par une simple option ; l'absence de prix fixé n'en entraîne donc pas, à elle seule, l'invalidité.","reasoning":"Distinguer pacte de préférence et promesse unilatérale.","legalRefs":["C. civ., art. 1123"],"verified":null,"source":{"label":"Objectif Barreau — Préparation estivale CRFPA 2026, corrigé sujet n°1 — corrigé p. 8–10","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-capital"}},{"id":"dp-capital-07","phase":"Conclusion","type":"single","stem":"La simple invitation adressée à Carla, qui n'a pas abouti à une cession, viole-t-elle déjà le pacte de préférence de Jean ?","options":["Oui, toute discussion avec un tiers est interdite","Non, le pacte est violé lorsque le promettant contracte avec un tiers sans respecter la priorité ; de simples pourparlers ne suffisent pas ici","Oui, si Carla connaît Jean","Oui, si Amélie envisage sérieusement de céder"],"answers":[1],"explanation":"Le corrigé conclut qu'une invitation à négocier ne constitue pas, en elle-même, la conclusion du contrat projeté avec un tiers et ne caractérise donc pas la violation invoquée.","reasoning":"Chercher si le contrat objet de la priorité a effectivement été conclu.","legalRefs":["C. civ., art. 1123"],"verified":null,"source":{"label":"Objectif Barreau — Préparation estivale CRFPA 2026, corrigé sujet n°1 — corrigé p. 8–10","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-capital"}}],"tags":["offre","pacte de préférence","rupture des pourparlers"],"warning":null},{"id":"dp-aude","title":"Maison dans l'Aude — Erreur, dol et restitutions","subject":"Droit des obligations","topic":"Vices du consentement","provider":"Objectif Barreau","year":2026,"source":{"label":"Objectif Barreau — Préparation estivale CRFPA 2026, corrigé sujet n°2","pages":"corrigé p. 1–6","kind":"correction-2026"},"scenario":"Alex et Amir achètent en 2022 une maison pour 450 000 €. Ils ont été séduits par le calme du quartier. Après leur installation, ils découvrent qu'une voisine mitoyenne, déjà connue avant la vente pour des comportements agressifs et harcelants, rend leur quotidien très difficile. Ils estiment la maison à 350 000 € compte tenu de cette situation. Le vendeur connaissait le problème mais ne l'avait pas révélé. Ils hésitent entre faire annuler la vente et conserver le bien tout en obtenant une indemnisation.","questions":[{"id":"dp-aude-01","phase":"Repérage","type":"single","stem":"Après la vente, les acquéreurs découvrent que la voisine mitoyenne était déjà connue pour un comportement agressif et harcelant. Quels fondements d'anéantissement le corrigé examine en priorité ?","options":["Erreur et dol","Force majeure et imprévision","Prescription acquisitive et compensation","Novation et délégation"],"answers":[0],"explanation":"Le corrigé traite d'abord les vices du consentement, notamment l'erreur et surtout le dol, avant d'écarter d'autres pistes.","reasoning":"Identifier un problème de consentement au moment de la formation.","legalRefs":["C. civ., art. 1128, 1130 et s."],"verified":null,"source":{"label":"Objectif Barreau — Préparation estivale CRFPA 2026, corrigé sujet n°2 — corrigé p. 1–6","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-aude"}},{"id":"dp-aude-02","phase":"Application","type":"single","stem":"L'environnement calme et serein peut-il être regardé comme déterminant du consentement des acquéreurs ?","options":["Jamais, car l'environnement est extérieur à l'immeuble","Oui, le corrigé admet qu'au vu des faits ils auraient pu ne pas acheter ou acheter à des conditions substantiellement différentes","Seulement si le voisin est copropriétaire","Uniquement si le vendeur l'a écrit dans l'acte"],"answers":[1],"explanation":"Le caractère déterminant s'apprécie in concreto. Le dossier indique que le calme du quartier était précisément un élément ayant séduit les acquéreurs.","reasoning":"Relier la croyance erronée à la décision de contracter.","legalRefs":["C. civ., art. 1130"],"verified":null,"source":{"label":"Objectif Barreau — Préparation estivale CRFPA 2026, corrigé sujet n°2 — corrigé p. 1–6","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-aude"}},{"id":"dp-aude-03","phase":"Application","type":"single","stem":"Le caractère excusable de l'erreur est-il absolument certain ?","options":["Oui, automatiquement pour un particulier","Non : le corrigé présente une discussion et renvoie à l'appréciation des juges, notamment sur l'idée qu'ils auraient pu interroger le voisinage","Non, car toute erreur d'un acquéreur est inexcusable","Oui, car trois visites rendent toute erreur excusable"],"answers":[1],"explanation":"Le corrigé oppose l'absence de compétence locale des acquéreurs à la possibilité qu'une enquête de voisinage ait révélé les nuisances. La conclusion dépend donc de l'appréciation in concreto.","reasoning":"Quand le corrigé hésite, conserver l'incertitude au lieu de transformer la solution en règle absolue.","legalRefs":["C. civ., art. 1132"],"verified":null,"source":{"label":"Objectif Barreau — Préparation estivale CRFPA 2026, corrigé sujet n°2 — corrigé p. 1–6","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-aude"}},{"id":"dp-aude-04","phase":"Qualification","type":"single","stem":"Pourquoi le dol apparaît-il comme un fondement plus solide dans le corrigé ?","options":["Parce qu'il n'exige ni tromperie ni caractère déterminant","Parce que la dissimulation intentionnelle du vendeur peut être retenue et que l'erreur provoquée par dol est toujours excusable","Parce que le dol rend tout contrat inexistant","Parce qu'il supprime tout délai de prescription"],"answers":[1],"explanation":"Le dol suppose une tromperie intentionnelle déterminante. Lorsqu'il est caractérisé, l'article 1139 neutralise notamment l'objection tirée du caractère inexcusable de l'erreur.","reasoning":"Chercher l'intention du vendeur de dissimuler une information déterminante.","legalRefs":["C. civ., art. 1137 à 1139"],"verified":null,"source":{"label":"Objectif Barreau — Préparation estivale CRFPA 2026, corrigé sujet n°2 — corrigé p. 1–6","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-aude"}},{"id":"dp-aude-05","phase":"Règle","type":"single","stem":"Quelle est la nature de la nullité pour erreur ou dol et son délai d'action selon le corrigé ?","options":["Nullité absolue, 30 ans","Nullité relative, cinq ans à compter de la découverte de l'erreur ou du dol","Nullité relative, deux ans à compter de la vente","Nullité absolue, cinq ans à compter de la vente"],"answers":[1],"explanation":"Les vices du consentement sont sanctionnés par une nullité relative. L'article 1144 fait courir le délai à compter de la découverte de l'erreur ou du dol.","reasoning":"Qualifier la nullité puis déterminer le point de départ spécial.","legalRefs":["C. civ., art. 1131 et 1144"],"verified":null,"source":{"label":"Objectif Barreau — Préparation estivale CRFPA 2026, corrigé sujet n°2 — corrigé p. 1–6","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-aude"}},{"id":"dp-aude-06","phase":"Application","type":"single","stem":"Si la vente est annulée, quelle affirmation est correcte concernant l'occupation de la maison pendant plusieurs années ?","options":["Aucune valeur de jouissance ne peut jamais être restituée après une nullité","Le vendeur peut demander la valeur de la jouissance/une indemnité d'occupation dans le cadre des restitutions, même si la vente a été annulée pour son dol","Seul l'acquéreur peut demander une indemnité d'occupation","L'indemnité est automatiquement égale à 20 % du prix"],"answers":[1],"explanation":"L'article 1352-3 inclut les fruits et la valeur de la jouissance dans la restitution. L'arrêt du 9 avril 2026 a censuré le rejet d'une demande d'indemnité d'occupation au seul motif de l'effet rétroactif de l'annulation.","reasoning":"Après la nullité, raisonner séparément sur chaque restitution.","legalRefs":["C. civ., art. 1178, 1352 et 1352-3 ; Cass. 3e civ., 9 avr. 2026, n° 24-17.405"],"verified":{"status":"officiel","label":"Cour de cassation, 9 avril 2026, n°24-17.405","url":"https://www.legifrance.gouv.fr/juri/id/JURITEXT000053915702"},"source":{"label":"Objectif Barreau — Préparation estivale CRFPA 2026, corrigé sujet n°2 — corrigé p. 1–6","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-aude"}},{"id":"dp-aude-07","phase":"Règle","type":"single","stem":"Les acquéreurs peuvent-ils demander la rescision pour lésion de plus des 7/12 sur le fondement de l'article 1674 ?","options":["Oui, tout acquéreur d'un immeuble le peut","Non, ce mécanisme bénéficie au vendeur de l'immeuble et les données du dossier ne remplissent de toute façon pas le seuil","Oui, dès que le prix payé dépasse de 20 % la valeur","Non, parce que la lésion n'existe jamais en matière immobilière"],"answers":[1],"explanation":"Le corrigé rappelle que l'article 1674 ouvre la rescision au vendeur lésé de plus des 7/12, pas à l'acquéreur qui estime avoir payé trop cher.","reasoning":"Vérifier à la fois le titulaire de l'action et le seuil.","legalRefs":["C. civ., art. 1674"],"verified":null,"source":{"label":"Objectif Barreau — Préparation estivale CRFPA 2026, corrigé sujet n°2 — corrigé p. 1–6","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-aude"}},{"id":"dp-aude-08","phase":"Règle","type":"single","stem":"Les acquéreurs victimes du dol qui choisissent de conserver la vente peuvent-ils demander l'indemnisation d'un excès de prix ?","options":["Non, seule la nullité est possible","Oui : la Cour de cassation a admis en 2026 l'action en indemnisation d'un excès de prix","Oui, mais seulement si le vendeur est professionnel","Non, car l'excès de prix est toujours une lésion"],"answers":[1],"explanation":"Le corrigé s'appuie sur Cass. 3e civ., 28 mai 2026, n° 24-20.821 : l'acquéreur victime d'un dol qui ne demande pas l'annulation peut agir en indemnisation d'un excès de prix. L'arrêt statue formellement sous l'empire des anciens articles 1116 et 1382 ; la V1.1 le présente donc comme la jurisprudence mobilisée par le corrigé, sans prétendre qu'il tranche expressément le régime des contrats conclus sous le droit réformé.","reasoning":"Identifier d'abord le choix de la victime : conserver la vente plutôt que demander la nullité. Le corrigé mobilise l'arrêt du 28 mai 2026 pour admettre une indemnisation de l'excès de prix. Point de prudence : l'arrêt concernait le droit antérieur à la réforme de 2016, ce qui doit être distingué de sa transposition pédagogique au contrat de 2022 du cas.","legalRefs":["C. civ., art. 1178 et 1240 ; Cass. 3e civ., 28 mai 2026, n°24-20.821"],"verified":{"status":"officiel","label":"Cass. 3e civ., 28 mai 2026, n°24-20.821 — arrêt sous droit antérieur, vérifié","url":"https://www.legifrance.gouv.fr/juri/id/JURITEXT000054167521"},"source":{"label":"Objectif Barreau — Préparation estivale CRFPA 2026, corrigé sujet n°2 — corrigé p. 1–6","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-aude"}},{"id":"dp-aude-09","phase":"Conclusion","type":"single","stem":"Une clause par laquelle les parties renoncent à toute indemnité peut-elle neutraliser à l'avance l'action délictuelle fondée sur le dol du vendeur ?","options":["Oui, toujours","Non selon le corrigé, la responsabilité délictuelle pour dol ne peut être exclue à l'avance par une telle clause","Oui, dès lors que l'acquéreur est majeur","Oui, si la clause figure dans un acte authentique"],"answers":[1],"explanation":"Le corrigé considère que la clause ne peut priver par avance la victime du dol de sa réparation extracontractuelle.","reasoning":"Identifier la nature délictuelle de l'action avant d'interpréter la clause.","legalRefs":["C. civ., art. 1240 ; principes d'ordre public de la responsabilité délictuelle"],"verified":null,"source":{"label":"Objectif Barreau — Préparation estivale CRFPA 2026, corrigé sujet n°2 — corrigé p. 1–6","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-aude"}}],"tags":["erreur","dol","nullité","restitutions","excès de prix"],"warning":null},{"id":"dp-techtop","title":"Tech'Top — Hausse des coûts et imprévision","subject":"Droit des obligations","topic":"Force obligatoire et imprévision","provider":"Objectif Barreau","year":2026,"source":{"label":"Objectif Barreau — Préparation estivale CRFPA 2026, corrigé sujet n°2","pages":"corrigé p. 6–8","kind":"correction-2026"},"scenario":"Dans le cadre de son activité, Alex a souscrit un contrat de maintenance informatique de 24 mois pour 550 € HT, avec un tarif annoncé comme ferme et non révisable. À la suite d'événements géopolitiques et d'une forte augmentation du coût de certaines pièces, le prestataire Tech'Top annonce une hausse unilatérale de 17 %. Alex refuse toute discussion et exige le maintien du tarif initial.","questions":[{"id":"dp-techtop-01","phase":"Repérage","type":"single","stem":"Tech'Top est lié par un contrat de maintenance de 24 mois à 550 € HT, présenté comme ferme et non révisable. Une hausse de ses coûts le conduit à annoncer +17 %. Quelle règle faut-il mobiliser en premier ?","options":["La force obligatoire du contrat","La responsabilité du fait des choses","La gestion d'affaires","La prescription acquisitive"],"answers":[0],"explanation":"Avant l'imprévision, il faut constater que les conditions tarifaires convenues s'imposent aux parties et ne se modifient pas unilatéralement.","reasoning":"Commencer par le droit commun de la modification du contrat.","legalRefs":["C. civ., art. 1103 et 1193"],"verified":null,"source":{"label":"Objectif Barreau — Préparation estivale CRFPA 2026, corrigé sujet n°2 — corrigé p. 6–8","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-techtop"}},{"id":"dp-techtop-02","phase":"Conclusion","type":"single","stem":"Tech'Top peut-elle imposer seule la hausse de 17 % ?","options":["Oui, si ses coûts ont réellement augmenté","Non, sauf fondement contractuel ou légal permettant cette modification","Oui, à condition de prévenir quinze jours avant","Oui, car le contrat est entre professionnels"],"answers":[1],"explanation":"Le corrigé écarte la modification unilatérale du prix dans ce contrat au regard de la force obligatoire et de l'absence de mécanisme convenu.","reasoning":"Chercher une clause de variation ou un pouvoir légal avant d'admettre une hausse unilatérale.","legalRefs":["C. civ., art. 1103 et 1193"],"verified":null,"source":{"label":"Objectif Barreau — Préparation estivale CRFPA 2026, corrigé sujet n°2 — corrigé p. 6–8","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-techtop"}},{"id":"dp-techtop-03","phase":"Règle","type":"multiple","stem":"Quelles conditions appartiennent au mécanisme d'imprévision de l'article 1195 ?","options":["Un changement de circonstances imprévisible lors de la conclusion","Une exécution devenue excessivement onéreuse","L'absence d'acceptation du risque par la partie qui l'invoque","Une simple baisse de rentabilité, même minime, suffit"],"answers":[0,1,2],"explanation":"L'article 1195 exige un changement imprévisible rendant l'exécution excessivement onéreuse pour une partie qui n'avait pas accepté d'en assumer le risque.","reasoning":"Tester les trois verrous du texte avant de passer à la procédure.","legalRefs":["C. civ., art. 1195"],"verified":null,"source":{"label":"Objectif Barreau — Préparation estivale CRFPA 2026, corrigé sujet n°2 — corrigé p. 6–8","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-techtop"}},{"id":"dp-techtop-04","phase":"Application","type":"single","stem":"Une clause stipulant un prix ferme et non révisable peut-elle être prise en compte comme acceptation du risque écartant l'article 1195 ?","options":["Non, jamais","Oui, le corrigé l'analyse comme faisant obstacle au mécanisme d'imprévision dans le dossier","Seulement si elle est manuscrite","Seulement si le prix dépasse 1 500 €"],"answers":[1],"explanation":"L'article 1195 n'est pas d'ordre public. Le corrigé estime que la clause de prix ferme/non révisable traduit ici l'acceptation du risque de variation.","reasoning":"Vérifier si les parties ont contractuellement réparti le risque.","legalRefs":["C. civ., art. 1195"],"verified":null,"source":{"label":"Objectif Barreau — Préparation estivale CRFPA 2026, corrigé sujet n°2 — corrigé p. 6–8","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-techtop"}},{"id":"dp-techtop-05","phase":"Règle","type":"single","stem":"Si l'article 1195 est applicable, la partie qui demande une renégociation doit-elle cesser d'exécuter le contrat pendant les discussions ?","options":["Oui","Non, elle continue à exécuter ses obligations pendant la renégociation","Oui, sauf autorisation du juge","Seulement si elle est créancière"],"answers":[1],"explanation":"Le mécanisme d'imprévision impose la poursuite de l'exécution pendant la renégociation.","reasoning":"Ne pas confondre demande de renégociation et exception d'inexécution.","legalRefs":["C. civ., art. 1195"],"verified":null,"source":{"label":"Objectif Barreau — Préparation estivale CRFPA 2026, corrigé sujet n°2 — corrigé p. 6–8","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-techtop"}},{"id":"dp-techtop-06","phase":"Application","type":"single","stem":"Le refus catégorique du client de renégocier constitue-t-il automatiquement une faute de mauvaise foi ?","options":["Oui, toujours","Non : l'exigence de bonne foi s'apprécie concrètement et le corrigé n'en déduit pas automatiquement une responsabilité dans ce contrat","Oui, si la hausse dépasse 10 %","Non, car la bonne foi n'existe pas entre professionnels"],"answers":[1],"explanation":"L'article 1104 impose la bonne foi, mais le corrigé souligne que l'existence d'une obligation de renégocier ne se déduit pas automatiquement des circonstances. Une argumentation contraire pouvait être discutée.","reasoning":"Ne pas transformer la bonne foi en pouvoir général de réécriture du contrat.","legalRefs":["C. civ., art. 1104"],"verified":null,"source":{"label":"Objectif Barreau — Préparation estivale CRFPA 2026, corrigé sujet n°2 — corrigé p. 6–8","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-techtop"}},{"id":"dp-techtop-07","phase":"Conclusion","type":"single","stem":"Quelle solution synthétique correspond au corrigé ?","options":["La hausse de 17 % s'impose immédiatement","Le tarif contractuel demeure applicable ; Tech'Top ne peut imposer la hausse et l'imprévision est fortement compromise par la répartition contractuelle du risque","Le contrat devient automatiquement nul","Le client doit accepter une hausse d'au moins 8,5 %"],"answers":[1],"explanation":"Le corrigé maintient la force du prix convenu et écarte, sur les faits, la voie permettant à Tech'Top d'obtenir la hausse qu'elle réclame.","reasoning":"Faire converger force obligatoire, clause de risque et bonne foi.","legalRefs":["C. civ., art. 1103, 1193, 1195"],"verified":null,"source":{"label":"Objectif Barreau — Préparation estivale CRFPA 2026, corrigé sujet n°2 — corrigé p. 6–8","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-techtop"}}],"tags":["force obligatoire","imprévision","bonne foi"],"warning":null},{"id":"dp-maite","title":"Maïté et Gabriel — Construire un raisonnement de preuve","subject":"Droit des obligations","topic":"Preuve des obligations","provider":"Pré-Barreau","year":2026,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°1","pages":"corrigé p. 1–3","kind":"correction-2026"},"scenario":"Maïté réclame d'abord 1 600 € à Gabriel au titre d'un bail de deux mois. Elle dispose surtout d'un e-mail où Gabriel rappelle le bien, la durée et le prix, mais aucun contrat formel n'a été signé. Elle lui avait aussi prêté 1 000 € contre une reconnaissance de dette. Après que Gabriel lui a remis une enveloppe censée contenir 1 000 €, Maïté lui a rendu le titre ; elle découvre plus tard que l'enveloppe ne contenait que 750 €. Une ancienne compagne de Gabriel propose de témoigner.","questions":[{"id":"dp-maite-01","phase":"Repérage","type":"single","stem":"Gabriel conteste l'existence d'un bail de deux mois à 1 600 €. Qui doit, en principe, prouver l'existence de l'obligation de payer ?","options":["Gabriel, parce qu'il conteste","Maïté, parce qu'elle réclame l'exécution de l'obligation","Le juge d'office","Le notaire"],"answers":[1],"explanation":"Celui qui réclame l'exécution d'une obligation doit la prouver. Maïté se prétend créancière des 1 600 €.","reasoning":"Commencer par la charge de la preuve avant les modes de preuve.","legalRefs":["C. civ., art. 1353, al. 1"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°1 — corrigé p. 1–3","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-maite"}},{"id":"dp-maite-02","phase":"Règle","type":"single","stem":"Un acte juridique civil portant sur 1 600 € doit, en principe, être prouvé par…","options":["tout moyen","un écrit sous signature privée ou authentique, le seuil réglementaire étant 1 500 €","deux témoins","un aveu judiciaire uniquement"],"answers":[1],"explanation":"Le corrigé applique l'article 1359 et le seuil de 1 500 € fixé par décret.","reasoning":"Qualifier l'objet comme acte juridique puis comparer sa valeur au seuil.","legalRefs":["C. civ., art. 1359 ; décret n°80-533 du 15 juillet 1980 modifié"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°1 — corrigé p. 1–3","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-maite"}},{"id":"dp-maite-03","phase":"Application","type":"single","stem":"Le courriel de Gabriel contenant ses nom et prénom au bas du message constitue-t-il, à lui seul, une signature électronique fiable au sens de l'article 1367 ?","options":["Oui, nécessairement","Non, le corrigé estime que la simple mention des nom et prénom ne suffit pas à établir la fiabilité exigée","Oui, dès que l'adresse e-mail est personnelle","Non, car aucun courriel ne peut être un écrit"],"answers":[1],"explanation":"Le courriel est bien un écrit, mais la signature électronique doit reposer sur un procédé fiable d'identification lié à l'acte. Le corrigé considère la simple mention du nom insuffisante pour en faire un acte sous signature privée parfait.","reasoning":"Distinguer l'existence d'un écrit de la valeur probatoire d'un écrit signé.","legalRefs":["C. civ., art. 1365 et 1367 ; Civ. 1re, 30 sept. 2010"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°1 — corrigé p. 1–3","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-maite"}},{"id":"dp-maite-04","phase":"Qualification","type":"single","stem":"Le même courriel peut-il néanmoins constituer un commencement de preuve par écrit ?","options":["Non, jamais","Oui, s'il émane de celui qui conteste l'acte et rend vraisemblable ce qui est allégué","Oui, mais il devient alors une preuve parfaite","Seulement si le montant est inférieur à 1 500 €"],"answers":[1],"explanation":"Le corrigé estime que le message peut remplir les critères de l'article 1362 : écrit, émanation de Gabriel et vraisemblance du bail allégué.","reasoning":"Une pièce insuffisante comme preuve parfaite peut avoir une valeur supplétive.","legalRefs":["C. civ., art. 1362"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°1 — corrigé p. 1–3","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-maite"}},{"id":"dp-maite-05","phase":"Règle","type":"single","stem":"Que faut-il ajouter à un commencement de preuve par écrit pour suppléer l'écrit exigé ?","options":["Rien","Un autre moyen de preuve qui le corrobore","Toujours un acte authentique","Une expertise graphologique obligatoire"],"answers":[1],"explanation":"L'article 1361 exige la corroboration par un autre moyen de preuve. Le dossier n'en fournit pas pour le bail.","reasoning":"Tester l'étape de corroboration avant de conclure.","legalRefs":["C. civ., art. 1361"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°1 — corrigé p. 1–3","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-maite"}},{"id":"dp-maite-06","phase":"Application","type":"single","stem":"Sur le bail de 1 600 €, quelle conclusion retient le corrigé avec les éléments disponibles ?","options":["Maïté a certainement une preuve parfaite","En l'état, elle ne devrait pas pouvoir établir suffisamment le bail, sauf à obtenir un élément corroborant le courriel","Gabriel est automatiquement condamné car il a écrit le montant","La preuve est libre car il s'agit d'un bail"],"answers":[1],"explanation":"Le courriel peut être un commencement de preuve par écrit mais aucun élément corroborant n'est donné ; le corrigé conclut donc défavorablement en l'état.","reasoning":"Assembler charge, admissibilité et force des preuves.","legalRefs":["C. civ., art. 1359, 1361, 1362"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°1 — corrigé p. 1–3","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-maite"}},{"id":"dp-maite-07","phase":"Repérage","type":"single","stem":"Pour le prêt de 1 000 €, Maïté avait une reconnaissance de dette mais l'a volontairement rendue à Gabriel après un remboursement prétendu intégral. Quel effet cette remise produit-elle ?","options":["Aucun","Une présomption simple de libération du débiteur","Une renonciation irrévocable à toute créance","Une novation"],"answers":[1],"explanation":"La remise volontaire au débiteur de l'original sous signature privée du titre de créance vaut présomption simple de libération.","reasoning":"Repérer la présomption légale qui déplace concrètement la charge de la preuve.","legalRefs":["C. civ., art. 1342-9 et 1354"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°1 — corrigé p. 1–3","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-maite"}},{"id":"dp-maite-08","phase":"Application","type":"single","stem":"L'ex-compagne de Gabriel se dit prête à témoigner qu'il n'a volontairement rendu que 750 €. Quelle proposition correspond au corrigé ?","options":["Le témoignage est juridiquement interdit","Le paiement et son absence peuvent se prouver par tous moyens ; ce témoignage peut donc être pris en compte, mais sa force relève de l'appréciation souveraine du juge","Le témoignage vaut preuve parfaite irréfragable","Le témoignage est nul parce qu'elle est une ex-compagne"],"answers":[1],"explanation":"Le paiement se prouve par tous moyens. Le témoignage est admissible pour tenter de renverser la présomption, mais le corrigé ne garantit pas qu'il convaincra le juge compte tenu notamment du contexte relationnel.","reasoning":"Distinguer admissibilité de la preuve et force de conviction.","legalRefs":["C. civ., art. 1342-8, 1342-9"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°1 — corrigé p. 1–3","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-maite"}}],"tags":["preuve","écrit électronique","commencement de preuve","paiement"],"warning":null},{"id":"dp-aristide","title":"Aristide — Offre, promesse et pacte en concurrence","subject":"Droit des obligations","topic":"Avant-contrats et formation","provider":"Pré-Barreau","year":2026,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°1","pages":"corrigé p. 4–10","kind":"correction-2026"},"scenario":"Aristide souhaite louer une maison neuve. Une annonce publique mentionne le bien, un loyer de 2 400 € et une durée de trois ans. Adrien répond vouloir louer à ces conditions. Entre-temps, Aristide a conclu avec Olivia un accord lui donnant deux mois pour décider de prendre le bien à bail à 2 300 €. Plus anciennement encore, il avait promis à sa voisine Clémence de lui proposer prioritairement la maison s'il décidait de la louer. Aristide finit par traiter avec Adrien avant la fin du délai d'Olivia.","questions":[{"id":"dp-aristide-01","phase":"Qualification","type":"single","stem":"L'annonce d'Aristide décrivant précisément la maison, la durée et le loyer est-elle nécessairement une offre de bail à toute personne qui répond ?","options":["Oui, nécessairement","Non selon le corrigé : le bail conserve une dimension intuitu personae et la proposition publique est analysée comme une invitation à entrer en pourparlers faute de fermeté","Oui, parce que le prix est déterminé","Non, car une annonce immobilière n'a jamais d'effet juridique"],"answers":[1],"explanation":"Le corrigé considère que le propriétaire conserve le choix de son locataire ; la proposition publique n'est donc pas suffisamment ferme pour valoir offre.","reasoning":"Même avec des éléments précis, vérifier la fermeté et les réserves implicites.","legalRefs":["C. civ., art. 1114"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°1 — corrigé p. 4–10","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-aristide"}},{"id":"dp-aristide-02","phase":"Qualification","type":"single","stem":"Le courrier d'Adrien du 17 novembre, qui propose sans réserve de louer aux conditions de l'annonce, est qualifié de…","options":["offre de bail","acceptation d'une offre déjà formée","pacte de préférence","promesse unilatérale"],"answers":[0],"explanation":"Puisque l'annonce n'est qu'une invitation, la réponse précise et ferme d'Adrien devient elle-même une offre faite à Aristide.","reasoning":"Lorsque la première proposition n'est pas une offre, tester la réponse comme nouvelle offre.","legalRefs":["C. civ., art. 1113 et 1114"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°1 — corrigé p. 4–10","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-aristide"}},{"id":"dp-aristide-03","phase":"Application","type":"single","stem":"Aristide répond le 13 janvier qu'il accepte de louer aux conditions proposées et Adrien reçoit le message. Quelle conséquence ?","options":["Aucun contrat ne peut être formé par e-mail","Un contrat de bail est en principe formé le 13 janvier par rencontre de l'offre et de l'acceptation","Le contrat ne se forme que le 1er février","Le contrat exige un acte authentique"],"answers":[1],"explanation":"L'acceptation sans réserve est reçue par l'offrant le 13 janvier : en principe, le contrat est conclu à cette date.","reasoning":"Appliquer la théorie de la réception à l'acceptation.","legalRefs":["C. civ., art. 1118 et 1121"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°1 — corrigé p. 4–10","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-aristide"}},{"id":"dp-aristide-04","phase":"Règle","type":"single","stem":"Adrien peut-il se prévaloir lui-même du fait que son offre du 17 novembre avait peut-être dépassé un délai raisonnable afin de revenir sur le contrat après l'acceptation ?","options":["Oui, toujours","Non selon le corrigé : la caducité pour dépassement du délai est une protection dont l'offrant peut se prévaloir ; l'acceptant ne peut l'invoquer pour défaire sa propre acceptation","Oui, si deux mois se sont écoulés","Oui, car toute offre sans délai expire après 30 jours"],"answers":[1],"explanation":"Le corrigé applique la solution selon laquelle l'offrant, et non l'acceptant, peut se prévaloir de l'expiration de l'offre. Il conclut au maintien du bail avec Adrien.","reasoning":"Identifier qui est titulaire de la protection liée à la caducité.","legalRefs":["C. civ., art. 1117 ; Soc., 30 mai 2018"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°1 — corrigé p. 4–10","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-aristide"}},{"id":"dp-aristide-05","phase":"Qualification","type":"single","stem":"L'accord du 18 novembre avec Olivia, par lequel Aristide est déjà engagé à louer si Olivia opte dans les deux mois, constitue…","options":["un pacte de préférence","une promesse unilatérale de bail","une offre révocable sans limite","un contrat de bail déjà définitif"],"answers":[1],"explanation":"Il ne manque que le consentement du bénéficiaire : l'accord correspond à la définition de la promesse unilatérale de l'article 1124.","reasoning":"Repérer un droit d'option réservé au bénéficiaire.","legalRefs":["C. civ., art. 1124"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°1 — corrigé p. 4–10","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-aristide"}},{"id":"dp-aristide-06","phase":"Application","type":"single","stem":"Aristide révoque la promesse le 14 janvier ; Olivia lève l'option le 16, avant l'échéance du 18 janvier. La révocation empêche-t-elle la formation du contrat promis ?","options":["Oui","Non, la révocation pendant le délai d'option n'empêche pas la formation du contrat promis","Oui, sauf si Olivia avait déjà payé un acompte","Non, mais uniquement si la promesse est notariée"],"answers":[1],"explanation":"L'article 1124, alinéa 2, neutralise la révocation intervenue pendant le temps laissé au bénéficiaire pour opter.","reasoning":"Comparer dates de révocation, fin de l'option et levée de l'option.","legalRefs":["C. civ., art. 1124, al. 2"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°1 — corrigé p. 4–10","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-aristide"}},{"id":"dp-aristide-07","phase":"Application","type":"single","stem":"Cependant, Aristide avait déjà loué la maison à Adrien le 13 janvier. Olivia peut-elle faire annuler ce bail au seul motif qu'il a été conclu pendant son délai d'option ?","options":["Oui, automatiquement","Non : l'article 1124 exige aussi que le tiers ait connu l'existence de la promesse ; le dossier ne l'établit pas pour Adrien","Oui, si Olivia lève l'option ensuite","Non, car une promesse unilatérale ne crée jamais aucun droit"],"answers":[1],"explanation":"Le contrat avec le tiers est nul s'il a été conclu en violation de la promesse avec un tiers qui en connaissait l'existence. Le corrigé relève que la connaissance d'Adrien n'est pas établie.","reasoning":"Ne pas oublier la condition subjective tenant au tiers.","legalRefs":["C. civ., art. 1124, al. 3"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°1 — corrigé p. 4–10","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-aristide"}},{"id":"dp-aristide-08","phase":"Conclusion","type":"single","stem":"Quel recours reste à Olivia si elle ne peut obtenir la maison ?","options":["Aucun","Une responsabilité contractuelle contre Aristide pour violation de la promesse, avec indemnisation de son dommage","Une action pénale automatique contre Adrien","Une rescision pour lésion"],"answers":[1],"explanation":"Le promettant a contracté avec un tiers pendant le délai d'option et a ainsi violé son engagement. L'inexécution étant définitive, le corrigé admet une action en responsabilité contractuelle.","reasoning":"Quand l'exécution en nature est bloquée par un contrat tiers maintenu, envisager les dommages-intérêts.","legalRefs":["C. civ., art. 1231 et 1231-1"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°1 — corrigé p. 4–10","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-aristide"}},{"id":"dp-aristide-09","phase":"Qualification","type":"single","stem":"L'accord ancien avec Clémence, selon lequel elle sera prioritaire si Aristide décide de louer, constitue…","options":["une promesse unilatérale","un pacte de préférence valable même sans loyer fixé","une simple obligation morale","une offre perpétuelle"],"answers":[1],"explanation":"Le pacte de préférence organise un droit de priorité ; le prix ou le loyer du contrat futur n'a pas à être déterminé dès la conclusion du pacte.","reasoning":"Repérer une priorité conditionnée par la décision future de contracter.","legalRefs":["C. civ., art. 1123"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°1 — corrigé p. 4–10","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-aristide"}},{"id":"dp-aristide-10","phase":"Conclusion","type":"single","stem":"Adrien connaissait l'existence du pacte de Clémence, mais elle lui avait dit ne pas être sûre de vouloir la maison. Clémence peut-elle obtenir substitution ou nullité ?","options":["Oui, car la connaissance du pacte suffit","Non, faute de preuve qu'Adrien connaissait aussi son intention de s'en prévaloir ; elle conserve toutefois une action contractuelle contre Aristide pour la perte de chance","Oui, car toute violation d'un pacte annule le contrat tiers","Non et elle n'a aucun recours"],"answers":[1],"explanation":"L'article 1123 exige la double connaissance par le tiers de l'existence du pacte et de l'intention du bénéficiaire de s'en prévaloir. Ici la seconde fait défaut, mais la violation du pacte ouvre une réparation contre le promettant.","reasoning":"Distinguer remèdes réels contre le contrat tiers et responsabilité contre le promettant.","legalRefs":["C. civ., art. 1123"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°1 — corrigé p. 4–10","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-aristide"}}],"tags":["offre","promesse unilatérale","pacte de préférence"],"warning":null},{"id":"dp-francois","title":"François — Fichier illicite, confirmation et prêt","subject":"Droit des obligations","topic":"Validité et ensembles contractuels","provider":"Pré-Barreau","year":2026,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°2","pages":"corrigé p. 1–7","kind":"correction-2026"},"scenario":"François achète pour 110 000 € un fichier de plus de 90 000 contacts que Marc présente comme fiable et conforme au RGPD. Dès le lendemain, François apprend que le fichier contient des données problématiques et a été constitué illicitement. Il décide pourtant de poursuivre l'opération et conclut un prêt bancaire destiné précisément à financer cette acquisition. La CNIL intervient ensuite et l'exploitation du fichier devient impossible. François veut récupérer le prix et se libérer du prêt.","questions":[{"id":"dp-francois-01","phase":"Repérage","type":"single","stem":"François achète 110 000 € un fichier client présenté comme conforme au RGPD ; il découvre qu'il provient de piratages et ne peut légalement être exploité. Quels fondements de nullité le corrigé examine ?","options":["Erreur, dol, objet illicite, contrepartie illusoire et but illicite","Seulement la lésion","Seulement la force majeure","Compensation et confusion"],"answers":[0],"explanation":"Le corrigé passe systématiquement en revue plusieurs conditions de validité du contrat, ce qui illustre la méthode de consultation lorsqu'un même fait peut recevoir plusieurs qualifications.","reasoning":"Ne pas s'arrêter au premier fondement plausible lorsque plusieurs sanctions convergent.","legalRefs":["C. civ., art. 1128, 1130 s., 1162, 1163, 1169"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°2 — corrigé p. 1–7","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-francois"}},{"id":"dp-francois-02","phase":"Application","type":"single","stem":"L'affirmation mensongère du vendeur selon laquelle le fichier est conforme au RGPD peut-elle constituer le dol ?","options":["Non, un mensonge commercial n'est jamais un dol","Oui, si le vendeur savait la déclaration fausse et l'a utilisée pour obtenir un consentement déterminé par cette qualité","Seulement si l'acheteur est consommateur","Seulement si le mensonge est écrit dans l'acte"],"answers":[1],"explanation":"Le corrigé retient les éléments matériel et intentionnel : Marc connaissait l'origine frauduleuse et affirmait pourtant la conformité afin d'obtenir l'accord de François.","reasoning":"Démontrer tromperie, intention, origine et caractère déterminant.","legalRefs":["C. civ., art. 1130 et 1137"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°2 — corrigé p. 1–7","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-francois"}},{"id":"dp-francois-03","phase":"Qualification","type":"single","stem":"La cession d'un fichier client constitué en violation des règles de protection des données peut-elle être analysée comme portant sur une prestation illicite ?","options":["Non, jamais","Oui, le corrigé s'appuie notamment sur la jurisprudence relative à la cession de fichiers non conformes à la réglementation des données","Seulement si le prix est excessif","Seulement après une sanction définitive de la CNIL"],"answers":[1],"explanation":"Le corrigé considère que l'objet de la prestation du cédant est illicite, la cession portant sur un fichier qui ne peut être licitement exploité.","reasoning":"Tester la licéité de la prestation indépendamment des vices du consentement.","legalRefs":["C. civ., art. 1162 et 1163 ; Com., 25 juin 2013"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°2 — corrigé p. 1–7","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-francois"}},{"id":"dp-francois-04","phase":"Application","type":"single","stem":"Pourquoi le fichier peut-il aussi être qualifié de contrepartie illusoire ?","options":["Parce qu'il coûte trop cher","Parce qu'il existe formellement mais ne procure aucun avantage réel exploitable à François pour des raisons juridiques","Parce que toute donnée personnelle est hors commerce","Parce qu'un fichier numérique n'est pas une prestation"],"answers":[1],"explanation":"Le corrigé applique l'article 1169 : François verse 110 000 € en contrepartie d'un fichier qui, en raison de son illicéité, ne peut lui procurer l'avantage économique attendu.","reasoning":"Distinguer contrepartie dérisoire (très faible) et illusoire (avantage seulement apparent).","legalRefs":["C. civ., art. 1169"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°2 — corrigé p. 1–7","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-francois"}},{"id":"dp-francois-05","phase":"Règle","type":"single","stem":"François apprend l'illicéité puis poursuit volontairement l'opération en obtenant le prêt et le paiement du prix. Quel mécanisme devient central ?","options":["La confirmation","La novation","La compensation","La prescription"],"answers":[0],"explanation":"L'exécution volontaire en connaissance de la cause de nullité peut valoir confirmation d'une nullité relative.","reasoning":"Après avoir trouvé la nullité, toujours vérifier si elle a été couverte.","legalRefs":["C. civ., art. 1182"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°2 — corrigé p. 1–7","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-francois"}},{"id":"dp-francois-06","phase":"Application","type":"single","stem":"Quels fondements sont susceptibles d'être couverts par cette confirmation selon le corrigé ?","options":["Erreur, dol et contrepartie illusoire","Objet illicite et but illicite","Toutes les nullités sans distinction","Aucun fondement"],"answers":[0],"explanation":"Le corrigé qualifie l'erreur, le dol et la contrepartie illusoire de causes de nullité relative pouvant être confirmées. L'objet et le but illicites relèvent de la nullité absolue et ne peuvent être couverts.","reasoning":"Qualifier chaque nullité comme relative ou absolue avant d'appliquer la confirmation.","legalRefs":["C. civ., art. 1179, 1180, 1181, 1182"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°2 — corrigé p. 1–7","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-francois"}},{"id":"dp-francois-07","phase":"Conclusion","type":"single","stem":"Après confirmation, François est-il totalement privé de toute action en nullité de la cession ?","options":["Oui","Non, il peut encore invoquer les causes de nullité absolue tirées de l'illicéité de l'objet ou du but","Oui, sauf s'il rembourse le prêt","Non, mais uniquement sur le fondement de l'erreur"],"answers":[1],"explanation":"La confirmation emporte renonciation aux moyens relatifs couverts, mais elle ne valide pas une atteinte à l'intérêt général sanctionnée par une nullité absolue.","reasoning":"Ne pas confondre confirmation partielle des moyens et validation générale du contrat.","legalRefs":["C. civ., art. 1182"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°2 — corrigé p. 1–7","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-francois"}},{"id":"dp-francois-08","phase":"Repérage","type":"single","stem":"Le prêt bancaire est expressément destiné à financer l'acquisition du fichier, et François connaissait déjà l'illicéité lorsqu'il l'a conclu. Le corrigé envisage la nullité du prêt principalement au titre…","options":["d'un but illicite","d'une erreur sur la personne","d'une lésion de plus des 7/12","d'une incapacité de la banque"],"answers":[0],"explanation":"Le financement d'une opération que l'emprunteur sait illicite peut contaminer le but poursuivi par le contrat de prêt.","reasoning":"Examiner le contrat de financement pour lui-même, pas seulement comme accessoire économique.","legalRefs":["C. civ., art. 1162"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°2 — corrigé p. 1–7","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-francois"}},{"id":"dp-francois-09","phase":"Règle","type":"single","stem":"À défaut de nullité, quel autre mécanisme peut faire disparaître le prêt si la cession disparaît ?","options":["La caducité d'un ensemble contractuel","La confusion","La prescription extinctive immédiate","La remise de dette légale"],"answers":[0],"explanation":"L'article 1186 permet la caducité d'un contrat lorsque plusieurs contrats participent à une même opération et que les conditions d'interdépendance sont remplies.","reasoning":"Après la disparition d'un contrat, tester l'indivisibilité objective ou subjective de l'ensemble.","legalRefs":["C. civ., art. 1186"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°2 — corrigé p. 1–7","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-francois"}},{"id":"dp-francois-10","phase":"Conclusion","type":"single","stem":"Selon le corrigé, quelle voie est la plus favorable à François concernant le prêt lorsque les conditions sont réunies ?","options":["La nullité, car elle conduit à des restitutions pouvant lui permettre de récupérer les intérêts déjà versés","La caducité, car elle efface toujours rétroactivement tous les intérêts","Aucune, le prêt est toujours indépendant","La compensation automatique avec le prix"],"answers":[0],"explanation":"Le corrigé conclut que le prêt peut être anéanti et indique que la nullité est plus intéressante pour l'emprunteur en raison du régime des restitutions.","reasoning":"Comparer les effets pratiques des différents fondements, pas seulement leur possibilité théorique.","legalRefs":["C. civ., art. 1178, 1186, 1352-6 et 1352-7"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°2 — corrigé p. 1–7","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-francois"}}],"tags":["dol","objet illicite","contrepartie illusoire","confirmation","caducité"],"warning":null},{"id":"dp-georges","title":"Donation de Georges — Dépendance ou insanité ?","subject":"Droit des obligations","topic":"Consentement et insanité d'esprit","provider":"Pré-Barreau","year":2026,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°2","pages":"corrigé p. 8–10","kind":"correction-2026"},"scenario":"Georges, 84 ans, s'est progressivement isolé sous l'influence de sa compagne, gardienne de son immeuble. Celle-ci le pressait de faire une donation de 30 000 € et menaçait de le quitter. La donation est toutefois consentie non à la compagne mais à sa nièce. Georges connaissait parallèlement une dégradation de ses facultés intellectuelles ; un acte notarié mentionne néanmoins qu'il était lucide. Après son décès, son fils souhaite récupérer la somme.","questions":[{"id":"dp-georges-01","phase":"Repérage","type":"single","stem":"Un octogénaire sous forte emprise psychologique de sa compagne consent une donation de 30 000 € à la nièce de celle-ci. Quels deux fondements le corrigé examine ?","options":["Abus de l'état de dépendance et insanité d'esprit","Lésion et force majeure","Pacte de préférence et dol incident","Compensation et novation"],"answers":[0],"explanation":"Le dossier oriente vers la violence par abus de dépendance et vers l'exigence de santé mentale pour consentir.","reasoning":"Identifier les faits affectant la liberté ou la lucidité du consentement.","legalRefs":["C. civ., art. 1143, 1129, 414-1, 901"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°2 — corrigé p. 8–10","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-georges"}},{"id":"dp-georges-02","phase":"Règle","type":"single","stem":"Depuis la loi de ratification de 2018, l'article 1143 exige que l'état de dépendance soit établi…","options":["à l'égard de n'importe quel tiers","à l'égard du cocontractant qui en abuse","uniquement à l'égard d'un employeur","uniquement sur le plan économique"],"answers":[1],"explanation":"L'abus de dépendance suppose un état de dépendance envers le cocontractant. La dépendance peut être psychologique, mais le lien doit viser la partie qui obtient l'engagement.","reasoning":"Vérifier qui exerce l'emprise et qui est juridiquement cocontractant.","legalRefs":["C. civ., art. 1143"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°2 — corrigé p. 8–10","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-georges"}},{"id":"dp-georges-03","phase":"Application","type":"single","stem":"Georges dépendait de sa compagne, mais la donataire est la nièce de celle-ci. Quel effet sur l'article 1143 ?","options":["Aucun, la dépendance envers un tiers suffit","Le fondement échoue selon le corrigé, faute de dépendance de Georges à l'égard de la donataire elle-même","La donation est automatiquement nulle","La nièce est réputée être la compagne"],"answers":[1],"explanation":"Même si l'emprise et l'abus paraissent factuellement forts, une condition textuelle manque : la dépendance à l'égard du cocontractant bénéficiaire de la donation.","reasoning":"Un cas pratique exige de vérifier toutes les conditions cumulatives, même si les faits paraissent moralement choquants.","legalRefs":["C. civ., art. 1143"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°2 — corrigé p. 8–10","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-georges"}},{"id":"dp-georges-04","phase":"Règle","type":"single","stem":"Après la mort de l'auteur, ses héritiers peuvent-ils attaquer une donation entre vifs pour insanité d'esprit ?","options":["Jamais","Oui, la donation entre vifs fait partie des actes pour lesquels l'action reste ouverte sous les conditions des articles 414-1 et 414-2","Uniquement si le montant dépasse 50 000 €","Uniquement si le donataire est un professionnel"],"answers":[1],"explanation":"Le corrigé relève l'exception permettant aux héritiers de discuter une donation entre vifs après le décès de son auteur.","reasoning":"Vérifier la recevabilité de l'héritier avant le fond.","legalRefs":["C. civ., art. 414-1, 414-2 et 901"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°2 — corrigé p. 8–10","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-georges"}},{"id":"dp-georges-05","phase":"Application","type":"single","stem":"Un certificat médical antérieur évoque une dégradation des facultés et des voisins disent Georges délirant le jour de l'acte, mais le notaire a constaté sa lucidité. Quelle conclusion est rigoureuse ?","options":["La nullité est certaine","La nullité est impossible","La question relève de l'appréciation souveraine : les éléments peuvent combattre la présomption de lucidité attachée aux constatations notariales, sans garantir le résultat","Le notaire décide lui-même définitivement de la validité"],"answers":[2],"explanation":"Le corrigé insiste sur la preuve d'un trouble mental suffisamment grave et contemporain. La mention du notaire est un élément fort, mais elle peut être combattue par d'autres preuves.","reasoning":"Conserver le degré d'incertitude du corrigé lorsqu'il dépend de l'appréciation des juges.","legalRefs":["C. civ., art. 414-1 et 901 ; Civ. 1re, 25 mai 1987"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°2 — corrigé p. 8–10","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-georges"}},{"id":"dp-georges-06","phase":"Conclusion","type":"single","stem":"Quel fondement paraît donc le plus utile dans ce dossier ?","options":["L'abus de dépendance est certain","L'insanité d'esprit est la voie la plus sérieuse, sous réserve de la preuve du trouble au moment de la donation","La lésion","L'imprévision"],"answers":[1],"explanation":"L'article 1143 bute sur l'identité du cocontractant. L'insanité d'esprit reste en revanche juridiquement ouverte et factuellement étayée, sans être certaine.","reasoning":"Éliminer le fondement auquel manque une condition puis hiérarchiser les pistes restantes.","legalRefs":["C. civ., art. 414-1, 414-2, 901, 1143"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°2 — corrigé p. 8–10","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-georges"}}],"tags":["violence","abus de dépendance","insanité d'esprit","donation"],"warning":null},{"id":"dp-studionova","title":"StudioNova — Porte-fort, inexécution et clause pénale","subject":"Droit des obligations","topic":"Inexécution contractuelle","provider":"Pré-Barreau","year":2026,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°3","pages":"corrigé p. 1–7","kind":"correction-2026"},"scenario":"StudioNova doit produire pour GreenWorld un film publicitaire et s'est personnellement engagée à ce qu'il soit réalisé par Marc Delcourt, réalisateur indépendant réputé. Elle a ensuite conclu avec Marc un contrat de 150 000 €, assorti d'une clause prévoyant 300 000 € en cas d'inexécution et interdisant au juge d'en modifier le montant. Marc accepte un projet concurrent incompatible et refuse finalement de réaliser le film. StudioNova livre un film avec un autre réalisateur, mais GreenWorld réclame réparation.","questions":[{"id":"dp-studio-01","phase":"Qualification","type":"single","stem":"StudioNova promet à GreenWorld qu'un réalisateur indépendant déterminé, Marc Delcourt, réalisera personnellement le film publicitaire. Quel mécanisme qualifie cet engagement ?","options":["Stipulation pour autrui","Porte-fort d'exécution","Gestion d'affaires","Délégation parfaite"],"answers":[1],"explanation":"StudioNova s'engage personnellement à ce qu'un tiers accomplisse un fait. Le corrigé qualifie l'engagement de porte-fort d'exécution.","reasoning":"Identifier qui est partie au contrat et qui est le tiers dont le fait est promis.","legalRefs":["C. civ., art. 1204"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°3 — corrigé p. 1–7","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-studionova"}},{"id":"dp-studio-02","phase":"Règle","type":"single","stem":"L'obligation du promettant dans ce porte-fort est analysée comme…","options":["une obligation de moyens","une obligation de résultat","une obligation naturelle","une simple recommandation"],"answers":[1],"explanation":"Le corrigé s'appuie sur la jurisprudence pour retenir une obligation de résultat : l'absence d'exécution du fait promis caractérise le manquement du promettant.","reasoning":"Qualifier l'intensité de l'obligation pour déterminer ce que le créancier doit prouver.","legalRefs":["C. civ., art. 1204 ; Soc., 3 mai 2012 ; Com., 11 oct. 2005"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°3 — corrigé p. 1–7","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-studionova"}},{"id":"dp-studio-03","phase":"Application","type":"single","stem":"GreenWorld réclame 10 000 € pour l'efficacité réduite de sa campagne et 200 000 € au titre d'un développement au Japon dont StudioNova n'avait pas été informée. Que retient le corrigé ?","options":["Les deux sont intégralement réparables","Seul le dommage de 10 000 € apparaît indemnisable ; le projet japonais est au mieux une perte de chance et surtout n'était pas prévisible lors du contrat","Aucun dommage n'est réparable","Seuls les 200 000 € sont réparables"],"answers":[1],"explanation":"En responsabilité contractuelle, le dommage doit notamment être certain et prévisible. Le projet japonais n'entrait pas dans l'économie connue du contrat, centré sur une campagne en France.","reasoning":"Pour chaque chef de préjudice, contrôler séparément certitude, causalité et prévisibilité.","legalRefs":["C. civ., art. 1231-3 ; règles sur la perte de chance"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°3 — corrigé p. 1–7","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-studionova"}},{"id":"dp-studio-04","phase":"Application","type":"single","stem":"Le refus de Marc Delcourt peut-il être invoqué par StudioNova comme force majeure pour échapper à son porte-fort ?","options":["Oui, car Marc est un tiers","Non, StudioNova s'était précisément engagée au résultat que ce tiers accomplisse le fait ; son refus ne permet pas de neutraliser l'engagement promis","Oui, dès qu'un tiers refuse","Oui, si Marc gagne davantage ailleurs"],"answers":[1],"explanation":"Le risque du refus du tiers est au cœur même de l'engagement de porte-fort. Le corrigé n'admet donc pas l'exonération sur ce fondement.","reasoning":"Une force majeure ne doit pas vider de sa substance le risque contractuellement assumé.","legalRefs":["C. civ., art. 1204 ; art. 1218"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°3 — corrigé p. 1–7","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-studionova"}},{"id":"dp-studio-05","phase":"Repérage","type":"single","stem":"StudioNova veut maintenant contraindre Marc à réaliser le film, conformément à leur contrat distinct. L'article 1221 permet-il en principe l'exécution forcée en nature ?","options":["Non, jamais pour une obligation de faire","Oui, après mise en demeure, sauf impossibilité ou disproportion manifeste dans les conditions du texte","Seulement si le contrat est notarié","Seulement si la prestation vaut moins de 5 000 €"],"answers":[1],"explanation":"Depuis la réforme, l'exécution forcée en nature est le principe, avec les exceptions de l'article 1221.","reasoning":"Commencer par le principe avant de rechercher l'exception.","legalRefs":["C. civ., art. 1221"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°3 — corrigé p. 1–7","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-studionova"}},{"id":"dp-studio-06","phase":"Application","type":"single","stem":"Pourquoi le corrigé écarte-t-il ici l'exécution forcée personnelle de Marc ?","options":["Parce que le prix est trop élevé","Parce que la création artistique est une prestation éminemment personnelle qu'on ne peut forcer matériellement sans porter atteinte aux libertés individuelles","Parce que toute obligation de résultat est inexécutable en nature","Parce qu'il n'y a pas eu de mise en demeure"],"answers":[1],"explanation":"Le caractère personnel et créatif de la prestation rend l'exécution forcée en nature juridiquement impossible dans l'analyse du corrigé.","reasoning":"Tester l'impossibilité juridique, pas seulement matérielle.","legalRefs":["C. civ., art. 1221 ; jurisprudence antérieure sur les obligations personnelles"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°3 — corrigé p. 1–7","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-studionova"}},{"id":"dp-studio-07","phase":"Qualification","type":"single","stem":"Le contrat stipule seulement qu'« en cas d'inexécution par l'une des parties, l'autre pourra résoudre le contrat ». Cette clause peut-elle fonctionner comme clause résolutoire ?","options":["Oui, toute formule générale suffit","Non selon le corrigé, l'article 1225 exige que les engagements dont l'inexécution entraîne la résolution soient précisément déterminés","Oui, si le contrat a été négocié","Non, car les clauses résolutoires sont interdites"],"answers":[1],"explanation":"La clause est trop générale : elle ne désigne pas précisément les obligations dont l'inexécution déclenchera le mécanisme.","reasoning":"Contrôler d'abord la validité formelle de la clause avant sa mise en œuvre.","legalRefs":["C. civ., art. 1225"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°3 — corrigé p. 1–7","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-studionova"}},{"id":"dp-studio-08","phase":"Conclusion","type":"single","stem":"À défaut de clause résolutoire valable, quelles voies restent envisagées par le corrigé pour mettre fin au contrat de Marc ?","options":["Résolution judiciaire ou résolution par notification, si leurs conditions de gravité et de procédure sont remplies","Aucune","Uniquement l'annulation pour dol","La caducité automatique"],"answers":[0],"explanation":"L'article 1224 reconnaît plusieurs modes de résolution. Le refus persistant d'exécuter une prestation centrale peut justifier les autres voies, sous leurs conditions propres.","reasoning":"Une clause inefficace n'épuise pas les autres remèdes légaux.","legalRefs":["C. civ., art. 1224, 1226, 1227 et 1228"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°3 — corrigé p. 1–7","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-studionova"}},{"id":"dp-studio-09","phase":"Qualification","type":"single","stem":"La stipulation imposant 300 000 € à Marc en cas d'inexécution, dans un contrat où sa rémunération est 150 000 €, constitue…","options":["une astreinte judiciaire","une clause pénale","un dépôt de garantie","une clause de dédit"],"answers":[1],"explanation":"Elle fixe forfaitairement et à l'avance les dommages-intérêts dus en cas d'inexécution, avec un effet comminatoire.","reasoning":"Repérer une évaluation conventionnelle anticipée du dommage.","legalRefs":["C. civ., art. 1231-5"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°3 — corrigé p. 1–7","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-studionova"}},{"id":"dp-studio-10","phase":"Application","type":"single","stem":"La clause ajoute que le juge ne pourra jamais modifier les 300 000 €. Quel est le bon raisonnement ?","options":["Toute la clause pénale est nulle","La stipulation qui retire au juge son pouvoir de modération/augmentation est réputée non écrite ; la clause pénale peut subsister et le juge peut réduire une pénalité manifestement excessive","Le juge est lié par la volonté des parties","Le montant est automatiquement divisé par deux"],"answers":[1],"explanation":"L'article 1231-5 interdit de neutraliser le pouvoir judiciaire de révision. Le corrigé estime en outre que 300 000 € pourrait apparaître manifestement excessif au regard du préjudice réellement subi.","reasoning":"Séparer la stipulation illicite sur le pouvoir du juge du mécanisme de clause pénale lui-même.","legalRefs":["C. civ., art. 1231-5 ; art. 1184"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°3 — corrigé p. 1–7","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-studionova"}}],"tags":["porte-fort","responsabilité contractuelle","exécution forcée","résolution","clause pénale"],"warning":null},{"id":"dp-horizon","title":"Horizon Jeunes — Mineur, parents et association","subject":"Droit des obligations","topic":"Responsabilité du fait d'autrui","provider":"Pré-Barreau","year":2026,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°3","pages":"corrigé p. 8–12","kind":"correction-2026"},"scenario":"Paul, 15 ans, est hébergé dans un foyer géré par une association à la suite d'un accord contractuel avec sa mère. Pendant une sortie, Sophie, bénévole et sœur du président de l'association, est seule chargée de surveiller treize adolescents. Elle s'éloigne pour un appel personnel malgré des instructions de surveillance étroite. Paul tente alors un vol et frappe violemment le commerçant qui l'intercepte. La victime cherche tous les responsables possibles.","questions":[{"id":"dp-horizon-01","phase":"Repérage","type":"single","stem":"Paul, 15 ans, frappe un commerçant après avoir tenté de voler. Le fait qu'il soit mineur empêche-t-il de caractériser une faute civile personnelle ?","options":["Oui","Non, la faute civile est objective et peut être retenue malgré la minorité","Oui, sauf émancipation","Oui, tant qu'il n'a pas 16 ans"],"answers":[1],"explanation":"Le corrigé rappelle qu'une faute peut être caractérisée sans exiger la conscience pleine des actes ; le coup volontaire constitue un comportement fautif.","reasoning":"Ne pas confondre imputabilité morale et faute civile objective.","legalRefs":["C. civ., art. 1240 et 1241 ; Ass. plén., 9 mai 1984"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°3 — corrigé p. 8–12","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-horizon"}},{"id":"dp-horizon-02","phase":"Règle","type":"single","stem":"Pour des faits d'octobre 2025, quel est le critère central du nouvel article 1242, alinéa 4, relatif aux parents ?","options":["La cohabitation matérielle au jour du dommage","L'exercice de l'autorité parentale, avec exception lorsque l'enfant est confié à un tiers par décision administrative ou judiciaire","La faute prouvée des parents","L'âge de 16 ans"],"answers":[1],"explanation":"La loi du 23 juin 2025, en vigueur depuis le 25 juin, a recentré le texte sur l'exercice de l'autorité parentale et prévoit l'exception liée à un placement par décision administrative ou judiciaire.","reasoning":"Avant d'appliquer une règle récente, fixer la date du fait dommageable.","legalRefs":["C. civ., art. 1242, al. 4 ; loi n°2025-568 du 23 juin 2025"],"verified":{"status":"officiel","label":"Légifrance, art. 1242 version depuis le 25 juin 2025","url":"https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000051786000/"},"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°3 — corrigé p. 8–12","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-horizon"}},{"id":"dp-horizon-03","phase":"Application","type":"single","stem":"Paul vit dans un foyer associatif en vertu d'un contrat conclu par sa mère, sans décision judiciaire ou administrative. Cette situation suffit-elle à faire cesser la responsabilité de ses parents au titre du nouvel article 1242 ?","options":["Oui, tout hébergement chez un tiers suffit","Non, l'exception textuelle vise le fait d'être confié à un tiers par une décision administrative ou judiciaire","Oui, si le foyer est une association","Oui, dès que le père voit rarement l'enfant"],"answers":[1],"explanation":"Le corrigé applique strictement la nouvelle exception : un placement contractuel ne suffit pas. Rien n'indique non plus que le père ait perdu l'exercice de l'autorité parentale.","reasoning":"Distinguer résidence/garde quotidienne et exercice juridique de l'autorité parentale.","legalRefs":["C. civ., art. 1242, al. 4"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°3 — corrigé p. 8–12","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-horizon"}},{"id":"dp-horizon-04","phase":"Conclusion","type":"single","stem":"Les deux parents peuvent-ils donc voir leur responsabilité de plein droit engagée sur les faits ?","options":["Non, seule la mère qui a la garde exclusive","Oui, dès lors qu'ils exercent tous deux l'autorité parentale et que les autres conditions sont réunies","Seulement si une faute de surveillance est prouvée","Non, car Paul vit en association"],"answers":[1],"explanation":"Le corrigé conclut à la responsabilité des deux parents, faute d'élément établissant une privation d'autorité parentale ou un placement relevant de l'exception légale.","reasoning":"Appliquer le critère légal, pas le vocabulaire courant de « garde exclusive ».","legalRefs":["C. civ., art. 1242, al. 4"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°3 — corrigé p. 8–12","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-horizon"}},{"id":"dp-horizon-05","phase":"Application","type":"single","stem":"Sophie, sœur du président de l'association, accompagne bénévolement la sortie mais reçoit des instructions précises et un véhicule. Peut-elle être qualifiée de préposée malgré l'absence de salaire ?","options":["Non, le salaire est indispensable","Oui, un lien de préposition peut exister dès lors qu'une autorité donne ordres et directives, même pour un service temporaire et gratuit","Oui, mais seulement si elle signe un CDI","Non, parce qu'elle est membre de la famille"],"answers":[1],"explanation":"Le corrigé s'appuie sur la conception fonctionnelle du lien de préposition : le pouvoir de direction suffit, même sans contrat de travail.","reasoning":"Rechercher le pouvoir d'autorité plutôt que l'étiquette contractuelle.","legalRefs":["C. civ., art. 1242, al. 5 ; Crim., 14 juin 1990"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°3 — corrigé p. 8–12","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-horizon"}},{"id":"dp-horizon-06","phase":"Application","type":"single","stem":"Sophie s'éloigne quinze minutes pour un appel personnel malgré l'instruction de surveiller étroitement les adolescents. Peut-elle conserver l'immunité du préposé ?","options":["Oui, toujours","Non selon le corrigé : elle agit sans autorisation et à des fins étrangères à ses attributions, ce qui caractérise un dépassement des limites de la mission","Oui, car aucune infraction pénale n'est commise","Non uniquement parce qu'elle est bénévole"],"answers":[1],"explanation":"Le corrigé applique l'exception à l'immunité issue de Costedoat : l'acte est accompli hors des limites de la mission.","reasoning":"Après avoir qualifié le lien de préposition, contrôler les limites de mission.","legalRefs":["Ass. plén., 25 févr. 2000, Costedoat"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°3 — corrigé p. 8–12","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-horizon"}},{"id":"dp-horizon-07","phase":"Repérage","type":"single","stem":"Indépendamment du fait de Sophie, l'association peut-elle avoir commis sa propre faute ?","options":["Non, une personne morale ne commet jamais de faute","Oui, en confiant seule treize adolescents en difficulté à une personne inexpérimentée malgré le besoin de surveillance","Non, puisque le dommage a été causé directement par Paul","Oui, mais seulement si elle est à but lucratif"],"answers":[1],"explanation":"Le corrigé retient une faute d'organisation propre à l'association, distincte de la responsabilité du fait du préposé.","reasoning":"Chercher un fait générateur propre du commettant en plus de la responsabilité du fait d'autrui.","legalRefs":["C. civ., art. 1240 et 1241"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°3 — corrigé p. 8–12","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-horizon"}},{"id":"dp-horizon-08","phase":"Qualification","type":"single","stem":"L'association peut-elle aussi être recherchée comme commettant du fait de Sophie ?","options":["Non, parce que Sophie est bénévole","Oui, le corrigé retient le lien de préposition et les conditions de l'article 1242, alinéa 5","Non, car seule la responsabilité personnelle de Sophie existe","Seulement si Paul est salarié"],"answers":[1],"explanation":"La responsabilité du commettant est distincte de la faute propre de l'association et peut être mobilisée lorsque le préposé a causé le dommage dans les fonctions auxquelles il est employé.","reasoning":"Cumuler les fondements possibles sans les confondre.","legalRefs":["C. civ., art. 1242, al. 5"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°3 — corrigé p. 8–12","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-horizon"}},{"id":"dp-horizon-09","phase":"Conclusion","type":"single","stem":"Les différents responsables peuvent-ils s'exonérer simplement en invoquant la faute des autres intervenants ?","options":["Oui, tout fait d'un tiers exonère","Non, le fait du tiers n'est exonératoire que s'il présente les caractères de la force majeure ; le corrigé ne les retrouve pas ici","Oui, si plusieurs personnes ont contribué au dommage","Oui, uniquement pour les parents"],"answers":[1],"explanation":"Le fait de Sophie n'est pas irrésistible pour Paul/les parents et le comportement de Paul n'est ni extérieur ni imprévisible pour la surveillante dans le raisonnement du corrigé.","reasoning":"En présence de plusieurs causes, distinguer obligation à la dette et recours entre responsables.","legalRefs":["Principes de la cause étrangère et de la force majeure"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°3 — corrigé p. 8–12","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-horizon"}}],"tags":["responsabilité des parents","préposé","commettant","faute"],"warning":null},{"id":"dp-theo","title":"Théo — Accident sans contact et pluralité de responsables","subject":"Droit des obligations","topic":"Accidents de la circulation","provider":"Pré-Barreau","year":2026,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°4","pages":"corrigé p. 1–7","kind":"correction-2026"},"scenario":"Lucas, salarié de Transvert, conduit une camionnette de livraison. Il dépasse Théo, cycliste distrait par son téléphone et ses écouteurs. Sans contact avec la camionnette, Théo perd le contrôle de son vélo et chute sur une barrière de chantier couchée sur le trottoir. Cette barrière appartient à Bâti Construct mais Kévin, salarié de cette société, l'avait détournée pendant son jour de repos pour ses loisirs personnels et l'avait laissée sans surveillance.","questions":[{"id":"dp-theo-01","phase":"Repérage","type":"single","stem":"Une camionnette dépasse un cycliste ; sans contact, le cycliste est surpris, chute et se blesse. La loi du 5 juillet 1985 peut-elle s'appliquer malgré l'absence de contact avec le véhicule ?","options":["Non, un choc matériel est indispensable","Oui, si le véhicule a joué un rôle quelconque dans l'accident et est donc impliqué","Oui, mais seulement si le conducteur a commis une infraction","Non, car un vélo est impliqué"],"answers":[1],"explanation":"En l'absence de contact, la victime doit démontrer le rôle quelconque du véhicule. La manœuvre de dépassement a ici déclenché la perte de contrôle.","reasoning":"Ne pas assimiler implication et causalité stricte.","legalRefs":["Loi n°85-677 du 5 juillet 1985, art. 1 et 2 ; jurisprudence sur l'implication"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°4 — corrigé p. 1–7","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-theo"}},{"id":"dp-theo-02","phase":"Application","type":"single","stem":"Lucas conduisait la camionnette de son employeur dans le cadre d'une livraison. Peut-il être qualifié de conducteur au sens de la loi de 1985 ?","options":["Non, parce qu'il n'est pas propriétaire","Oui, il avait la maîtrise de fait du véhicule","Non, parce qu'il est salarié","Oui, mais seulement avec un permis professionnel"],"answers":[1],"explanation":"Le conducteur est celui qui a la maîtrise de fait du véhicule. La propriété n'est pas exigée.","reasoning":"Distinguer conducteur et gardien.","legalRefs":["Loi du 5 juillet 1985 ; Civ. 2e, 29 mars 2012"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°4 — corrigé p. 1–7","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-theo"}},{"id":"dp-theo-03","phase":"Qualification","type":"single","stem":"Lucas est en même temps préposé de Transvert et agit dans sa mission sans faute intentionnelle. Quelle conséquence retient le corrigé sur l'action personnelle contre lui ?","options":["Il reste toujours personnellement tenu sous la loi Badinter","Il bénéficie de l'immunité du préposé et n'est pas tenu d'indemniser personnellement la victime dans ces circonstances","Il est automatiquement pénalement irresponsable","Son employeur ne peut jamais être recherché"],"answers":[1],"explanation":"Le corrigé applique l'immunité du préposé conducteur dès lors qu'il reste dans les limites de sa mission et n'a commis ni faute pénale intentionnelle constatée ni faute civile intentionnelle.","reasoning":"Après le régime spécial d'indemnisation, contrôler le statut personnel du conducteur.","legalRefs":["Ass. plén., 25 févr. 2000 ; Civ. 2e, 28 mai 2009"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°4 — corrigé p. 1–7","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-theo"}},{"id":"dp-theo-04","phase":"Application","type":"single","stem":"Transvert, propriétaire de la camionnette, peut-elle être regardée comme gardienne du véhicule ?","options":["Non, la garde est toujours transférée au salarié conducteur","Oui, le propriétaire est présumé gardien et le préposé n'acquiert en principe pas la garde lorsqu'il utilise la chose pour le compte et sous l'autorité du commettant","Non, car une société ne peut pas être gardienne","Oui seulement si Lucas était dirigeant"],"answers":[1],"explanation":"Le corrigé retient la garde de la camionnette par Transvert et conclut à une action utile contre la société au titre de la loi de 1985.","reasoning":"Vérifier si le préposé a une autonomie suffisante pour recevoir la garde.","legalRefs":["Loi du 5 juillet 1985 ; principes de la garde"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°4 — corrigé p. 1–7","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-theo"}},{"id":"dp-theo-05","phase":"Conclusion","type":"single","stem":"Contre qui la victime dispose-t-elle donc d'une action utile du côté de la camionnette selon le corrigé ?","options":["Lucas uniquement","Transvert, en qualité de gardienne de la camionnette","Ni Lucas ni Transvert","Le constructeur du véhicule"],"answers":[1],"explanation":"Lucas bénéficie de l'immunité du préposé, tandis que Transvert reste gardienne du véhicule impliqué.","reasoning":"Identifier le débiteur final de l'indemnisation après les immunités.","legalRefs":["Loi du 5 juillet 1985 ; art. 1242 pour le statut de préposé"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°4 — corrigé p. 1–7","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-theo"}},{"id":"dp-theo-06","phase":"Repérage","type":"single","stem":"Kévin avait pris une barrière de chantier de son employeur pour créer un skatepark personnel pendant son jour de repos et l'a laissée couchée sur le trottoir. Quels fondements le corrigé envisage contre lui ?","options":["Responsabilité pour faute et responsabilité du fait des choses","Responsabilité contractuelle uniquement","Garantie des vices cachés","Enrichissement injustifié"],"answers":[0],"explanation":"La barrière placée anormalement sur le trottoir permet d'envisager à la fois la faute de Kévin et son rôle comme gardien de la chose.","reasoning":"Lorsqu'une chose participe au dommage, penser au fait des choses en plus de la faute.","legalRefs":["C. civ., art. 1240, 1241 et 1242, al. 1"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°4 — corrigé p. 1–7","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-theo"}},{"id":"dp-theo-07","phase":"Qualification","type":"single","stem":"L'usage purement personnel de la barrière par Kévin, hors temps de travail et contre sa mission de livraison, a quelle conséquence ?","options":["Il reste nécessairement dans ses fonctions","Le corrigé retient un abus de fonctions, susceptible d'écarter l'immunité du préposé et la responsabilité du commettant","Il transfère automatiquement la propriété de la barrière","Il efface toute responsabilité"],"answers":[1],"explanation":"Kévin agit sans autorisation, à des fins étrangères à ses attributions et hors de la mission confiée. Le corrigé en déduit l'abus de fonctions.","reasoning":"Comparer concrètement acte commis et mission professionnelle.","legalRefs":["Jurisprudence sur l'abus de fonctions ; art. 1242, al. 5"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°4 — corrigé p. 1–7","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-theo"}},{"id":"dp-theo-08","phase":"Application","type":"single","stem":"Théo consultait son téléphone et écoutait de la musique. Sur l'action de droit commun contre Kévin, quel effet sa faute peut-elle avoir selon le corrigé ?","options":["Aucun effet possible","Une exonération partielle de Kévin si la faute de Théo a contribué au dommage, faute de force majeure permettant une exonération totale","Une exonération totale automatique","L'extinction de toute action contre quiconque"],"answers":[1],"explanation":"Le corrigé considère la faute de la victime causale mais non imprévisible/irrésistible pour Kévin ; elle ne conduit donc qu'à une réduction partielle sur ce fondement.","reasoning":"Ne pas transposer mécaniquement le régime Badinter à l'action de droit commun contre un autre responsable.","legalRefs":["Principes de responsabilité délictuelle et cause étrangère"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°4 — corrigé p. 1–7","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-theo"}},{"id":"dp-theo-09","phase":"Conclusion","type":"single","stem":"La société Bâti Construct, employeur de Kévin, est-elle finalement retenue comme responsable dans le corrigé ?","options":["Oui, toujours parce qu'elle est propriétaire de la barrière","Non : l'abus de fonctions emporte ici transfert de garde et exonère le commettant du fait du préposé","Oui, mais seulement pour moitié","Non, parce qu'une société ne répond jamais de ses salariés"],"answers":[1],"explanation":"Le corrigé conclut que la victime peut utilement agir contre Transvert et Kévin, mais pas contre Bâti Construct compte tenu de l'abus de fonctions.","reasoning":"Faire une conclusion acteur par acteur.","legalRefs":["C. civ., art. 1242, al. 1 et 5"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°4 — corrigé p. 1–7","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-theo"}}],"tags":["Badinter","implication","préposé","garde","fait des choses"],"warning":null},{"id":"dp-lumex","title":"Lumex — Incendie et produit défectueux","subject":"Droit des obligations","topic":"Produits défectueux et incendie","provider":"Pré-Barreau","year":2026,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°4","pages":"corrigé p. 8–11","kind":"correction-2026"},"scenario":"Isabelle achète une guirlande fabriquée par Lumex. Un défaut d'isolation, affectant toute une série, provoque un court-circuit et un incendie qui se propage à la maison des voisins, causant 12 000 € de dégâts. Lumex connaissait le défaut depuis plusieurs mois mais avait poursuivi les ventes avant de rappeler ses produits. Isabelle avait reçu l'avertissement et l'interdiction d'utiliser la guirlande, mais l'a tout de même branchée.","questions":[{"id":"dp-lumex-01","phase":"Repérage","type":"single","stem":"Un incendie part d'une guirlande défectueuse chez Isabelle et détruit partiellement la maison voisine. Isabelle avait été avertie du danger mais a continué à utiliser la guirlande. Quel premier fondement peut être invoqué contre elle ?","options":["La responsabilité pour faute","La responsabilité contractuelle des voisins","La garantie d'éviction","La gestion d'affaires"],"answers":[0],"explanation":"Ignorer volontairement une interdiction d'utilisation motivée par un risque d'incendie peut caractériser une faute causale au sens des articles 1240 et 1241.","reasoning":"Commencer par le comportement personnel de la détentrice.","legalRefs":["C. civ., art. 1240 et 1241"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°4 — corrigé p. 8–11","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-lumex"}},{"id":"dp-lumex-02","phase":"Qualification","type":"single","stem":"L'article 1242, alinéa 2, relatif aux incendies peut-il aussi être mobilisé contre Isabelle ?","options":["Non, il a été abrogé","Oui, à l'égard des tiers, si l'incendie a pris naissance dans un bien qu'elle détient et que sa faute ou celle d'une personne dont elle répond est prouvée","Oui, sans qu'aucune faute ne soit nécessaire","Seulement entre propriétaire et locataire"],"answers":[1],"explanation":"Le régime spécial du fait des incendies exige notamment la faute du détenteur à l'égard des tiers. Celle-ci est caractérisée dans le corrigé.","reasoning":"Ne pas confondre le régime des incendies avec une responsabilité de plein droit.","legalRefs":["C. civ., art. 1242, al. 2"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°4 — corrigé p. 8–11","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-lumex"}},{"id":"dp-lumex-03","phase":"Application","type":"single","stem":"Isabelle peut-elle s'exonérer en invoquant le fabricant qui a commercialisé une guirlande dangereuse ?","options":["Oui, tout fait du fabricant est force majeure","Non : même si ce fait lui est extérieur, elle avait reçu l'avertissement et pouvait éviter le dommage en cessant d'utiliser la guirlande ; l'irrésistibilité fait défaut","Oui, car elle n'a pas fabriqué le produit","Oui, car le produit était joli"],"answers":[1],"explanation":"La force majeure doit notamment être irrésistible. L'information reçue par Isabelle lui donnait précisément la possibilité d'éviter le risque.","reasoning":"Tester chaque caractère de la force majeure séparément.","legalRefs":["Principes de force majeure en responsabilité délictuelle"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°4 — corrigé p. 8–11","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-lumex"}},{"id":"dp-lumex-04","phase":"Qualification","type":"single","stem":"Le régime des produits défectueux des articles 1245 et suivants est-il applicable aux voisins qui n'ont pas acheté la guirlande au fabricant ?","options":["Non, seul l'acheteur peut agir","Oui, le producteur répond du défaut qu'il soit ou non lié par un contrat avec la victime","Seulement si les voisins sont consommateurs","Non, car le dommage est immobilier"],"answers":[1],"explanation":"Le régime bénéficie aux victimes du défaut indépendamment d'un lien contractuel avec le producteur.","reasoning":"Ne pas imposer une condition de contrat que le texte écarte.","legalRefs":["C. civ., art. 1245"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°4 — corrigé p. 8–11","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-lumex"}},{"id":"dp-lumex-05","phase":"Règle","type":"single","stem":"Pour un dommage matériel à un bien autre que le produit défectueux lui-même, quel seuil réglementaire s'applique actuellement ?","options":["50 €","500 €","1 500 €","5 000 €"],"answers":[1],"explanation":"L'article 1245-1 renvoie à un montant fixé par décret ; le décret n°2005-113, dans sa version en vigueur, fixe ce montant à 500 €.","reasoning":"Comparer le dommage de 12 000 € au seuil réglementaire.","legalRefs":["C. civ., art. 1245-1 ; décret n°2005-113 du 11 févr. 2005, art. 1"],"verified":{"status":"officiel","label":"Légifrance, art. 1245-1 + décret : 500 €","url":"https://www.legifrance.gouv.fr/loda/id/JORFTEXT000000239085/"},"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°4 — corrigé p. 8–11","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-lumex"}},{"id":"dp-lumex-06","phase":"Application","type":"single","stem":"Une guirlande dont un défaut d'isolation provoque un court-circuit et un incendie offre-t-elle la sécurité à laquelle on peut légitimement s'attendre ?","options":["Oui, si elle s'allume normalement avant l'incendie","Non, le défaut de sécurité est caractérisé","Oui, si une mise en garde est envoyée après la vente","Non seulement si le fabricant reconnaît sa faute"],"answers":[1],"explanation":"Le défaut est apprécié notamment au regard de la sécurité légitimement attendue au moment de la mise en circulation. Le corrigé retient clairement la défectuosité.","reasoning":"Qualifier le défaut indépendamment de la faute du producteur.","legalRefs":["C. civ., art. 1245-3"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°4 — corrigé p. 8–11","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-lumex"}},{"id":"dp-lumex-07","phase":"Repérage","type":"single","stem":"Le fabricant connaissait le problème d'isolation depuis mars 2025 mais a continué à commercialiser les guirlandes jusqu'en novembre. Cette conduite peut-elle permettre une action de droit commun en plus du régime des produits défectueux ?","options":["Non, le régime spécial exclut toujours tout autre fondement","Oui, le corrigé identifie une faute distincte du seul défaut : maintenir en circulation un produit dont le fabricant connaît la défectuosité","Oui, mais uniquement sur un fondement contractuel","Non, car la connaissance du défaut est indifférente en toute matière"],"answers":[1],"explanation":"L'article 1245-17 préserve certains autres droits. La jurisprudence exige alors un fondement distinct du seul défaut ; la poursuite de la commercialisation malgré la connaissance du danger peut constituer cette faute distincte.","reasoning":"Pour cumuler avec le droit commun, rechercher une faute autonome.","legalRefs":["C. civ., art. 1245-17, 1240, 1241 ; Civ. 1re, 15 nov. 2023, n°22-21.174"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°4 — corrigé p. 8–11","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-lumex"}},{"id":"dp-lumex-08","phase":"Conclusion","type":"single","stem":"Quelle conclusion synthétique retient le corrigé ?","options":["Les voisins n'ont de recours que contre Isabelle","Ils peuvent agir contre Isabelle et contre le fabricant, chacun sur les fondements dont les conditions sont réunies","Seul le fabricant peut être condamné","Aucun responsable, car Isabelle a ignoré la mise en garde"],"answers":[1],"explanation":"Le corrigé ouvre plusieurs voies : faute/incendie contre Isabelle, responsabilité du fait des produits défectueux et faute distincte contre Lumex.","reasoning":"Conclure par défendeur et par fondement.","legalRefs":["C. civ., art. 1240, 1242 al. 2, 1245 et s."],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°4 — corrigé p. 8–11","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-lumex"}}],"tags":["incendie","produit défectueux","faute","cause étrangère"],"warning":null},{"id":"dp-fabien","title":"Fabien — Action oblique et solidarité","subject":"Droit des obligations","topic":"Régime général de l'obligation","provider":"Pré-Barreau","year":2026,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°4","pages":"corrigé p. 12–14","kind":"correction-2026"},"scenario":"Fabien est devenu insolvable alors qu'un créancier lui réclame 100 000 €. Son père lui propose une donation de 100 000 €, qu'il refuse. Fabien possède aussi une créance de remboursement de 120 000 € contre Virginie, Hubert et Gabriel, co-emprunteurs solidaires. Le prêt est exigible depuis le 13 avril 2026. Hubert a obtenu personnellement un délai jusqu'au 13 avril 2027, mais Fabien ne veut poursuivre personne.","questions":[{"id":"dp-fabien-01","phase":"Repérage","type":"single","stem":"Fabien est insolvable et refuse d'agir contre trois emprunteurs qui lui doivent 120 000 €. Son propre créancier de 100 000 € veut agir. Quel mécanisme faut-il envisager ?","options":["L'action oblique","L'action en rescision","La compensation légale","La gestion d'affaires"],"answers":[0],"explanation":"L'action oblique permet au créancier d'exercer, pour le compte de son débiteur défaillant, les droits et actions patrimoniaux que celui-ci néglige d'exercer.","reasoning":"Repérer la carence du débiteur qui compromet les droits de son créancier.","legalRefs":["C. civ., art. 1341-1"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°4 — corrigé p. 12–14","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-fabien"}},{"id":"dp-fabien-02","phase":"Règle","type":"multiple","stem":"Quelles conditions sont centrales pour l'action oblique dans le raisonnement du corrigé ?","options":["Une carence du débiteur compromettant les droits du créancier","Une créance du créancier présentée comme certaine, liquide et exigible","Un droit patrimonial du débiteur qui n'est pas exclusivement attaché à sa personne","L'accord préalable du débiteur"],"answers":[0,1,2],"explanation":"Le corrigé vérifie l'intérêt à agir, la créance du créancier obliquant et la nature patrimoniale du droit exercé. Le consentement du débiteur défaillant n'est pas requis.","reasoning":"Structurer les conditions par personne : créancier, débiteur, droit exercé.","legalRefs":["C. civ., art. 1341-1 ; jurisprudence antérieure reprise par le corrigé"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°4 — corrigé p. 12–14","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-fabien"}},{"id":"dp-fabien-03","phase":"Application","type":"single","stem":"Le père de Fabien propose de lui donner 100 000 €, mais Fabien refuse. Son créancier peut-il accepter cette donation à sa place par voie oblique ?","options":["Oui","Non, l'acceptation d'une libéralité est une faculté personnelle d'acquérir un droit, et non un droit patrimonial déjà détenu que le créancier peut exercer","Oui, dès que Fabien est insolvable","Oui, si le père confirme son offre"],"answers":[1],"explanation":"Le corrigé distingue la simple faculté d'accepter une donation de la créance déjà née contre les emprunteurs.","reasoning":"L'action oblique conserve les droits existants ; elle ne permet pas de créer à la place du débiteur un droit qu'il refuse d'acquérir.","legalRefs":["C. civ., art. 1341-1"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°4 — corrigé p. 12–14","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-fabien"}},{"id":"dp-fabien-04","phase":"Application","type":"single","stem":"Le créancier peut-il en revanche exercer l'action en remboursement du prêt contre Virginie ?","options":["Non, car le prêt appartient personnellement à Fabien","Oui, il s'agit d'une créance patrimoniale déjà née et l'inertie de Fabien compromet les droits de son créancier","Non, parce que Virginie n'est pas la débitrice du créancier obliquant","Oui uniquement si Fabien l'autorise"],"answers":[1],"explanation":"L'action est exercée pour le compte de Fabien, précisément parce qu'il néglige son droit patrimonial.","reasoning":"Comprendre que le créancier obliquant n'agit pas en son nom sur sa propre créance contre Virginie.","legalRefs":["C. civ., art. 1341-1"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°4 — corrigé p. 12–14","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-fabien"}},{"id":"dp-fabien-05","phase":"Repérage","type":"single","stem":"Le contrat de prêt stipule que Virginie, Hubert et Gabriel sont tenus solidairement. Que peut réclamer Fabien — et donc son créancier agissant obliquement — à Virginie ?","options":["Un tiers de 120 000 € seulement","La totalité de 120 000 €, sous réserve des exceptions opposables","100 000 € au maximum parce que le créancier obliquant n'est lui-même créancier que de 100 000 €","Rien tant que les deux autres ne sont pas poursuivis"],"answers":[1],"explanation":"En solidarité passive, chacun des codébiteurs est tenu à toute la dette envers le créancier. L'action oblique exerce la créance de Fabien elle-même : le corrigé conclut à une condamnation de Virginie à payer 120 000 € à Fabien.","reasoning":"Distinguer montant de la créance exercée et montant de la créance personnelle du créancier obliquant.","legalRefs":["C. civ., art. 1310 et 1313"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°4 — corrigé p. 12–14","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-fabien"}},{"id":"dp-fabien-06","phase":"Application","type":"single","stem":"Hubert a obtenu personnellement un délai jusqu'au 13 avril 2027. Virginie peut-elle opposer ce terme au créancier qui la poursuit ?","options":["Oui, tout codébiteur profite de tout délai accordé à un autre","Non, le terme accordé à Hubert est une exception personnelle que Virginie ne peut opposer","Oui, car la solidarité partage les exceptions personnelles","Non, parce qu'un terme est juridiquement inexistant"],"answers":[1],"explanation":"L'article 1315 distingue les exceptions communes et les exceptions personnelles. Le délai accordé à Hubert est personnel à celui-ci.","reasoning":"Qualifier l'exception avant de savoir si elle circule entre codébiteurs.","legalRefs":["C. civ., art. 1305 et 1315"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°4 — corrigé p. 12–14","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-fabien"}},{"id":"dp-fabien-07","phase":"Conclusion","type":"single","stem":"À qui la somme obtenue par l'action oblique est-elle due ?","options":["Directement et exclusivement au créancier obliquant","À Fabien : le créancier exerce le droit pour le compte de son débiteur, la valeur réintégrant son patrimoine","À Virginie","Au père de Fabien"],"answers":[1],"explanation":"L'action oblique est conservatoire du patrimoine du débiteur ; le créancier n'acquiert pas un droit exclusif sur la créance exercée.","reasoning":"Ne pas confondre action oblique et action directe.","legalRefs":["C. civ., art. 1341-1"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°4 — corrigé p. 12–14","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-fabien"}},{"id":"dp-fabien-08","phase":"Contrôle qualité","type":"single","stem":"Le résumé introductif du corrigé de l'épreuve n°4 indique par erreur que Fabien aurait accordé à Hubert une « remise de dette de 50 % », alors que le sujet et le développement détaillé analysent un délai de paiement jusqu'au 13 avril 2027. Quelle donnée cette V1.1 retient-elle ?","options":["La remise de dette de 50 %","Le délai de paiement jusqu'au 13 avril 2027, conformément au sujet et au raisonnement détaillé du corrigé","Les deux à la fois","Aucune, le dossier est supprimé"],"answers":[1],"explanation":"La banque signale explicitement cette incohérence documentaire. Elle suit les faits du sujet original et le développement juridique détaillé du corrigé, qui portent tous deux sur un terme suspensif accordé à Hubert.","reasoning":"En cas d'incohérence interne d'une source pédagogique, ne pas la masquer : identifier la version soutenue par le sujet et le raisonnement développé.","legalRefs":["Sujet Pré-Barreau épreuve n°4, 3e consultation ; corrigé détaillé, p. 13–14"],"verified":null,"source":{"label":"Pré-Barreau — Formation pré-estivale 2026, corrigé épreuve n°4 — corrigé p. 12–14","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-fabien"}}],"tags":["action oblique","solidarité","terme"],"warning":"Le corrigé comporte une incohérence dans son résumé introductif : il évoque une remise de dette de 50 % alors que le sujet et le développement détaillé portent sur un délai de paiement. La V1.1 suit le sujet + le développement détaillé."},{"id":"dp-social-mobigo-vtc","title":"Mobigo — Le chauffeur VTC est-il réellement indépendant ?","subject":"Droit social","topic":"Qualification du contrat de travail","provider":"Pré-Barreau","year":2026,"source":{"label":"Pré-Barreau — Droit social, épreuve n°1 & corrigé 2026","pages":"sujet p. 1 · corrigé p. 1–5","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-social-mobigo-vtc"},"scenario":"Monsieur Lefèvre, immatriculé au RCS, travaille comme chauffeur VTC depuis janvier 2023 via la plateforme Mobigo. Le contrat est intitulé « contrat de partenariat ». Il n’a aucune clientèle propre : les courses proviennent exclusivement de l’algorithme. Mobigo fixe unilatéralement les tarifs, peut corriger le prix si le trajet est jugé « non optimal », laisse dix secondes pour accepter une course, réduit l’accès aux courses pendant 24 heures lorsque le taux de refus est trop élevé et menace de désactivation lorsque la note client passe sous 4,2/5. Après un signalement pour retard, son compte est définitivement désactivé le 2 juin 2026. Il demande la requalification en CDI.","questions":[{"id":"dp-social-mobigo-vtc-01","phase":"Repérage","type":"single","stem":"Le fait que le contrat soit intitulé « contrat de partenariat » empêche-t-il, à lui seul, une requalification en contrat de travail ?","options":["Oui, la qualification choisie par les parties s’impose au juge","Oui, sauf fraude démontrée","Non, le juge recherche les conditions de fait d’exercice de l’activité","Non, mais uniquement si le contrat est verbal"],"answers":[2],"explanation":"Le corrigé rappelle l’indisponibilité de la qualification : la dénomination donnée par les parties ne lie pas le juge, qui restitue leur exacte qualification aux faits et actes litigieux.","reasoning":"Commencer par neutraliser l’étiquette contractuelle puis examiner la réalité de la relation.","legalRefs":["CPC, art. 12","C. trav., art. L. 1221-1"],"verified":null,"source":{"label":"Pré-Barreau — Droit social, épreuve n°1 & corrigé 2026","pages":"sujet p. 1 · corrigé p. 1–5","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-social-mobigo-vtc"}},{"id":"dp-social-mobigo-vtc-02","phase":"Qualification","type":"single","stem":"Quelle est l’incidence de l’immatriculation de Monsieur Lefèvre au RCS ?","options":["Elle interdit toute requalification","Elle crée une présomption irréfragable de non-salariat","Elle crée une présomption simple de non-salariat qui peut être renversée","Elle vaut reconnaissance d’un contrat commercial par le conseil de prud’hommes"],"answers":[2],"explanation":"L’article L. 8221-6 instaure une présomption de non-salariat pour certaines personnes immatriculées, mais cette présomption peut être combattue si les conditions d’un lien de subordination juridique permanente sont établies.","reasoning":"Identifier d’abord la présomption, puis demander si les faits permettent de la renverser.","legalRefs":["C. trav., art. L. 8221-6","C. civ., art. 1353"],"verified":{"label":"Article L. 8221-6 vérifié sur Légifrance, version en vigueur en 2026.","url":"https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000044056617/2026-05-06"},"source":{"label":"Pré-Barreau — Droit social, épreuve n°1 & corrigé 2026","pages":"sujet p. 1 · corrigé p. 1–5","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-social-mobigo-vtc"}},{"id":"dp-social-mobigo-vtc-03","phase":"Règle","type":"single","stem":"Quels sont les trois éléments classiquement recherchés pour qualifier un contrat de travail ?","options":["Une prestation de travail, une rémunération et un lien de subordination","Une immatriculation, un salaire minimum et une exclusivité","Un écrit, une rémunération fixe et une ancienneté","Une prestation, une clientèle personnelle et une indépendance économique"],"answers":[0],"explanation":"Le corrigé structure la qualification autour d’une prestation de travail, d’une rémunération et surtout d’un lien de subordination.","reasoning":"Vérifier les trois critères sans réduire le contrat de travail au seul lien de subordination.","legalRefs":["C. trav., art. L. 1221-1","Cass. soc., 13 nov. 1996, n° 94-13.187"],"verified":null,"source":{"label":"Pré-Barreau — Droit social, épreuve n°1 & corrigé 2026","pages":"sujet p. 1 · corrigé p. 1–5","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-social-mobigo-vtc"}},{"id":"dp-social-mobigo-vtc-04","phase":"Règle","type":"single","stem":"Le lien de subordination est principalement caractérisé par le pouvoir de l’employeur de…","options":["fixer un prix et être propriétaire des locaux","donner des ordres et directives, contrôler leur exécution et sanctionner les manquements","exiger une exclusivité absolue et verser un salaire mensuel","choisir seul le lieu du siège social"],"answers":[1],"explanation":"Le critère juridique classique repose sur les pouvoirs de direction, de contrôle et de sanction.","reasoning":"Construire un faisceau d’indices en classant les faits sous direction / contrôle / sanction.","legalRefs":["Cass. soc., 13 nov. 1996, n° 94-13.187"],"verified":null,"source":{"label":"Pré-Barreau — Droit social, épreuve n°1 & corrigé 2026","pages":"sujet p. 1 · corrigé p. 1–5","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-social-mobigo-vtc"}},{"id":"dp-social-mobigo-vtc-05","phase":"Application","type":"multiple","stem":"Quels faits du dossier constituent des indices particulièrement forts de subordination ?","options":["La fixation unilatérale des tarifs et la correction tarifaire du trajet","Le contrôle des refus et de la note client","La réduction d’accès aux courses et la désactivation du compte","Le seul fait d’être immatriculé au RCS"],"answers":[0,1,2],"explanation":"Le corrigé rapproche ces éléments des pouvoirs de direction, contrôle et sanction déjà retenus dans la jurisprudence sur les plateformes. L’immatriculation au RCS est au contraire le point de départ de la présomption simple de non-salariat.","reasoning":"Ne pas compter les indices : les qualifier. Tarif/itinéraire = direction ; suivi/refus/note = contrôle ; réduction d’accès/désactivation = sanction.","legalRefs":["Cass. soc., 4 mars 2020, n° 19-13.316","Cass. soc., 28 nov. 2018, n° 17-20.079"],"verified":null,"source":{"label":"Pré-Barreau — Droit social, épreuve n°1 & corrigé 2026","pages":"sujet p. 1 · corrigé p. 1–5","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-social-mobigo-vtc"}},{"id":"dp-social-mobigo-vtc-06","phase":"Application","type":"single","stem":"L’absence de clientèle propre et l’intégration dans un service entièrement organisé par la plateforme sont-elles pertinentes ?","options":["Non, jamais","Oui, elles peuvent renforcer le faisceau d’indices lorsque la plateforme détermine unilatéralement les conditions d’exécution","Oui, elles suffisent toujours à elles seules à établir un contrat de travail","Uniquement si le chauffeur travaille à temps plein"],"answers":[1],"explanation":"Le service organisé n’est qu’un indice, mais il est pertinent lorsque les conditions d’exécution sont déterminées unilatéralement par la plateforme.","reasoning":"Utiliser le service organisé comme indice complémentaire, sans le transformer en critère autonome suffisant.","legalRefs":["Cass. soc., 27 sept. 2023, n° 20-22.465"],"verified":null,"source":{"label":"Pré-Barreau — Droit social, épreuve n°1 & corrigé 2026","pages":"sujet p. 1 · corrigé p. 1–5","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-social-mobigo-vtc"}},{"id":"dp-social-mobigo-vtc-07","phase":"Conclusion","type":"single","stem":"Au regard des seuls faits fournis, quelle conclusion retient le corrigé ?","options":["La requalification paraît sérieusement envisageable car les éléments de subordination sont caractérisés","La requalification est impossible du fait du RCS","Il faut nécessairement rejeter la demande faute de salaire mensuel","La désactivation du compte n’a aucune portée"],"answers":[0],"explanation":"Le corrigé considère que les différents éléments du lien de subordination sont caractérisés et que la relation semble pouvoir être requalifiée en contrat de travail.","reasoning":"Conclure de façon nuancée : « semble pouvoir être requalifiée », car la qualification résulte d’une appréciation factuelle.","legalRefs":["C. trav., art. L. 8221-6"],"verified":null,"source":{"label":"Pré-Barreau — Droit social, épreuve n°1 & corrigé 2026","pages":"sujet p. 1 · corrigé p. 1–5","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-social-mobigo-vtc"}}],"tags":["plateforme","VTC","contrat de travail","subordination"],"warning":null,"status":"ready"},{"id":"dp-social-mobigo-usage","title":"Mobigo — Peut-on supprimer une pause devenue un usage ?","subject":"Droit social","topic":"Usage d’entreprise","provider":"Pré-Barreau","year":2026,"source":{"label":"Pré-Barreau — Droit social, épreuve n°1 & corrigé 2026","pages":"sujet p. 1 · corrigé p. 6–8","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-social-mobigo-usage"},"scenario":"Depuis plusieurs années, tous les salariés de Mobigo bénéficient d’une pause supplémentaire de 15 minutes par demi-journée, en plus des pauses légales. Aucune note de service n’a créé cet avantage : il est entré dans la pratique de l’entreprise. Les contrats signés depuis 2025 en mentionnent simplement l’existence. Pour améliorer la productivité, l’employeur diffuse une note annonçant la suppression de cette pause au 1er septembre 2026. Le CSE découvre la décision au même moment que les salariés.","questions":[{"id":"dp-social-mobigo-usage-01","phase":"Qualification","type":"single","stem":"Une pratique non écrite accordant durablement la même pause à la collectivité de travail peut-elle constituer un usage d’entreprise ?","options":["Oui, si elle présente notamment généralité, constance et fixité","Non, un usage doit toujours être écrit","Oui, uniquement si le CSE l’a signé","Non, les pauses ne peuvent jamais faire l’objet d’un usage"],"answers":[0],"explanation":"Le corrigé retient la qualification d’usage au regard des critères matériels de généralité, constance et fixité.","reasoning":"Identifier la source de l’avantage avant d’étudier sa suppression.","legalRefs":["Jurisprudence relative aux usages d’entreprise"],"verified":null,"source":{"label":"Pré-Barreau — Droit social, épreuve n°1 & corrigé 2026","pages":"sujet p. 1 · corrigé p. 6–8","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-social-mobigo-usage"}},{"id":"dp-social-mobigo-usage-02","phase":"Règle","type":"multiple","stem":"Pour dénoncer unilatéralement un usage, quelles exigences sont retenues dans le corrigé ?","options":["Informer individuellement les salariés concernés ou susceptibles de l’être","Informer les institutions représentatives du personnel","Respecter un délai de prévenance suffisant","Obtenir l’accord individuel de chaque salarié dans tous les cas"],"answers":[0,1,2],"explanation":"La dénonciation suppose information individuelle, information des représentants du personnel et délai suffisant. L’accord de chaque salarié n’est pas exigé pour un usage non contractualisé.","reasoning":"Distinguer la dénonciation d’un usage de la modification d’une clause contractuelle.","legalRefs":["Cass. soc., 4 juill. 2012","Cass. soc., 10 févr. 1998","Cass. soc., 13 mars 2001"],"verified":null,"source":{"label":"Pré-Barreau — Droit social, épreuve n°1 & corrigé 2026","pages":"sujet p. 1 · corrigé p. 6–8","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-social-mobigo-usage"}},{"id":"dp-social-mobigo-usage-03","phase":"Application","type":"single","stem":"Le fait que le CSE découvre la suppression par la note déjà diffusée aux salariés pose-t-il difficulté ?","options":["Non, l’information peut être postérieure","Oui, le corrigé estime que le CSE n’a pas été informé en amont et que la dénonciation est irrégulière","Non, car Mobigo compte moins de 100 salariés","Oui, mais uniquement si le CSE vote contre"],"answers":[1],"explanation":"Le corrigé relève que le CSE a pris connaissance de la décision après sa formalisation : la procédure de dénonciation n’est donc pas régulière.","reasoning":"Contrôler la chronologie : la représentation du personnel doit être mise en mesure de réagir avant la disparition de l’usage.","legalRefs":["Jurisprudence sur la dénonciation des usages"],"verified":null,"source":{"label":"Pré-Barreau — Droit social, épreuve n°1 & corrigé 2026","pages":"sujet p. 1 · corrigé p. 6–8","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-social-mobigo-usage"}},{"id":"dp-social-mobigo-usage-04","phase":"Application","type":"single","stem":"Un préavis d’environ deux mois serait-il nécessairement suffisant ?","options":["Oui, deux mois constituent toujours le minimum légal","Non : le corrigé estime ce délai possiblement trop court pour un avantage appliqué depuis plusieurs années et suggère qu’environ trois mois serait préférable","Oui, car les salariés ont été informés","Non, le préavis doit toujours être d’un an"],"answers":[1],"explanation":"Le corrigé ne pose pas de délai légal uniforme. Il indique qu’un délai de deux mois pourrait être trop court et qu’un délai d’au moins trois mois serait préférable dans ces faits.","reasoning":"Ne pas transformer un exemple jurisprudentiel en délai légal absolu : raisonner sur le caractère suffisant du préavis.","legalRefs":["Cass. soc., 13 mars 2001","Cass. soc., 16 mars 1989"],"verified":null,"source":{"label":"Pré-Barreau — Droit social, épreuve n°1 & corrigé 2026","pages":"sujet p. 1 · corrigé p. 6–8","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-social-mobigo-usage"}},{"id":"dp-social-mobigo-usage-05","phase":"Qualification","type":"single","stem":"La simple mention de la pause dans les contrats signés depuis 2025 suffit-elle nécessairement à contractualiser l’avantage ?","options":["Oui, toute mention est une contractualisation","Non, le corrigé considère que la simple mention semble insuffisante ; il faut vérifier une véritable incorporation au champ contractuel","Oui, dès que le contrat est signé","Non, un usage ne peut jamais devenir contractuel"],"answers":[1],"explanation":"Le corrigé distingue une simple description de l’usage d’un véritable engagement contractuel. La première ne suffit pas nécessairement à contractualiser l’avantage.","reasoning":"Lire la clause : mention informative ou véritable engagement ? La réponse commande la possibilité d’une suppression unilatérale.","legalRefs":["Cass. soc., 2 mai 2001, n° 99-41.264","Cass. soc., 1er févr. 2012"],"verified":null,"source":{"label":"Pré-Barreau — Droit social, épreuve n°1 & corrigé 2026","pages":"sujet p. 1 · corrigé p. 6–8","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-social-mobigo-usage"}},{"id":"dp-social-mobigo-usage-06","phase":"Conclusion","type":"single","stem":"Quelle conduite pratique le corrigé recommande-t-il à Mobigo ?","options":["Maintenir la suppression telle quelle","Reprendre la procédure, informer les représentants du personnel et respecter un délai suffisant","Licencier les salariés qui conservent la pause","Faire signer une renonciation rétroactive"],"answers":[1],"explanation":"La dénonciation telle que mise en œuvre est irrégulière. Le corrigé conseille de reprendre la procédure correctement.","reasoning":"Conclure sur l’opposabilité immédiate de la dénonciation, puis proposer la régularisation.","legalRefs":["Jurisprudence sur la dénonciation des usages"],"verified":null,"source":{"label":"Pré-Barreau — Droit social, épreuve n°1 & corrigé 2026","pages":"sujet p. 1 · corrigé p. 6–8","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-social-mobigo-usage"}}],"tags":["usage","CSE","dénonciation","contrat de travail"],"warning":null,"status":"ready"},{"id":"dp-social-mobigo-essai","title":"Mobigo — Renouvellement et rupture de la période d’essai","subject":"Droit social","topic":"Période d’essai","provider":"Pré-Barreau","year":2026,"source":{"label":"Pré-Barreau — Droit social, épreuve n°1 & corrigé 2026","pages":"sujet p. 1 · corrigé p. 8–9","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-social-mobigo-essai"},"scenario":"Madame Fontaine est recrutée en CDI comme assistante de direction, statut agent de maîtrise. Son contrat prévoit une période d’essai de trois mois, renouvelable une fois. La période est renouvelée « par accord » entre les parties, sans autre précision dans l’énoncé. Mobigo rompt ensuite l’essai sans donner de motif. La salariée soutient que le renouvellement est irrégulier et que la rupture, intervenue dans un contexte de difficultés économiques alors que son poste n’a pas été remplacé, est abusive.","questions":[{"id":"dp-social-mobigo-essai-01","phase":"Repérage","type":"single","stem":"Quelle question doit être traitée en premier ?","options":["Le montant de l’indemnité de licenciement","La validité du renouvellement de la période d’essai","La qualification du poste de Madame Fontaine","La date de naissance de la salariée"],"answers":[1],"explanation":"Le corrigé insiste sur cet ordre : si le renouvellement est irrégulier, le contrat est devenu définitif et la rupture relève du licenciement, non de l’essai.","reasoning":"Toujours sécuriser l’existence même de la période d’essai au jour de la rupture avant d’étudier son abus.","legalRefs":["C. trav., art. L. 1221-21 à L. 1221-23"],"verified":null,"source":{"label":"Pré-Barreau — Droit social, épreuve n°1 & corrigé 2026","pages":"sujet p. 1 · corrigé p. 8–9","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-social-mobigo-essai"}},{"id":"dp-social-mobigo-essai-02","phase":"Règle","type":"multiple","stem":"Quelles conditions légales entourent le renouvellement de la période d’essai ?","options":["Un accord de branche étendu doit autoriser le renouvellement et en fixer les conditions","La possibilité de renouveler doit être expressément stipulée dans le contrat ou la lettre d’engagement","Le renouvellement ne peut intervenir qu’une fois","Un simple usage d’entreprise suffit toujours"],"answers":[0,1,2],"explanation":"Les articles L. 1221-21 et L. 1221-23 imposent ces conditions. Le corrigé ajoute l’exigence jurisprudentielle d’un accord exprès du salarié pendant la période initiale.","reasoning":"Vérifier source collective + clause initiale + consentement au renouvellement + durée totale.","legalRefs":["C. trav., art. L. 1221-21","C. trav., art. L. 1221-23"],"verified":{"label":"Articles L. 1221-21 et L. 1221-23 vérifiés sur Légifrance, droit en vigueur en 2026.","url":"https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000019071109/2026-05-09"},"source":{"label":"Pré-Barreau — Droit social, épreuve n°1 & corrigé 2026","pages":"sujet p. 1 · corrigé p. 8–9","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-social-mobigo-essai"}},{"id":"dp-social-mobigo-essai-03","phase":"Règle","type":"single","stem":"Pour un agent de maîtrise, quelle durée maximale légale le renouvellement compris ne peut-il dépasser ?","options":["4 mois","5 mois","6 mois","8 mois"],"answers":[2],"explanation":"L’article L. 1221-21 fixe à six mois la durée maximale, renouvellement compris, pour les agents de maîtrise et techniciens.","reasoning":"Identifier la catégorie professionnelle avant d’appliquer la durée plafond.","legalRefs":["C. trav., art. L. 1221-21"],"verified":{"label":"Durée maximale vérifiée sur Légifrance.","url":"https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000019071109/2026-05-09"},"source":{"label":"Pré-Barreau — Droit social, épreuve n°1 & corrigé 2026","pages":"sujet p. 1 · corrigé p. 8–9","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-social-mobigo-essai"}},{"id":"dp-social-mobigo-essai-04","phase":"Application","type":"single","stem":"Peut-on affirmer avec certitude, sur le seul énoncé, que le renouvellement est valable ?","options":["Oui, parce que le contrat prévoit le renouvellement","Non : l’énoncé ne permet pas de savoir si un accord de branche étendu le permet ni si l’accord exprès est intervenu pendant la période initiale","Oui, parce qu’il existe un accord entre les parties","Non, car toute période d’essai d’un agent de maîtrise est non renouvelable"],"answers":[1],"explanation":"Le corrigé conclut explicitement qu’il manque des informations pour trancher avec certitude.","reasoning":"Savoir conclure « informations insuffisantes » est une compétence CRFPA : ne jamais inventer la convention collective ou la date de l’accord.","legalRefs":["C. trav., art. L. 1221-21","C. trav., art. L. 1221-23"],"verified":null,"source":{"label":"Pré-Barreau — Droit social, épreuve n°1 & corrigé 2026","pages":"sujet p. 1 · corrigé p. 8–9","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-social-mobigo-essai"}},{"id":"dp-social-mobigo-essai-05","phase":"Règle","type":"single","stem":"Une rupture de période d’essai doit-elle, en principe, être motivée dans la lettre ?","options":["Oui, toujours","Non, mais le droit de rompre ne doit pas être détourné de la finalité de l’essai","Non, et aucun contrôle judiciaire n’est possible","Oui, seulement pour les agents de maîtrise"],"answers":[1],"explanation":"Le corrigé rappelle que l’essai n’a pas à être motivé, mais qu’une rupture peut être abusive lorsqu’elle repose sur un motif étranger à l’évaluation professionnelle.","reasoning":"Ne pas confondre absence d’obligation de motivation et liberté absolue de rompre.","legalRefs":["C. trav., art. L. 1221-20","C. trav., art. L. 1231-1"],"verified":{"label":"Finalité légale de la période d’essai vérifiée sur Légifrance.","url":"https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000019071111/2026-07-01"},"source":{"label":"Pré-Barreau — Droit social, épreuve n°1 & corrigé 2026","pages":"sujet p. 1 · corrigé p. 8–9","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-social-mobigo-essai"}},{"id":"dp-social-mobigo-essai-06","phase":"Conclusion","type":"single","stem":"Comment apprécier les difficultés économiques et l’absence de remplacement du poste ?","options":["L’absence de remplacement suffit à elle seule à établir l’abus","Ces éléments sont sans aucune pertinence","L’absence de remplacement ne suffit pas seule, mais combinée aux difficultés économiques elle peut contribuer à établir un motif non inhérent aux compétences ; l’employeur peut prouver l’inverse","Toute difficulté économique interdit légalement toute rupture d’essai"],"answers":[2],"explanation":"Le corrigé estime que les deux éléments peuvent, ensemble, aller dans le sens d’un détournement de la finalité de l’essai, tout en laissant à l’employeur la possibilité de démontrer un motif professionnel.","reasoning":"Construire un faisceau d’indices et rester prudent sur la conclusion.","legalRefs":["Cass. soc., 30 sept. 1992, n° 89-41.820","Cass. soc., 20 nov. 2007"],"verified":null,"source":{"label":"Pré-Barreau — Droit social, épreuve n°1 & corrigé 2026","pages":"sujet p. 1 · corrigé p. 8–9","kind":"correction-2026","provider":"Pré-Barreau","caseId":"dp-social-mobigo-essai"}}],"tags":["période d’essai","renouvellement","abus"],"warning":"Le corrigé lui-même conclut que certaines données factuelles manquent : la V1.2 conserve cette incertitude au lieu de la combler.","status":"ready"},{"id":"dp-social-bricopro-groupe","title":"BRICOPRO — Prêt de main-d’œuvre, groupe et coemploi","subject":"Droit social","topic":"Relations de groupe et prêt de main-d’œuvre","provider":"Objectif Barreau","year":2026,"source":{"label":"Objectif Barreau — Droit social, corrigé sujet n°1 (Étudiants) 2026","pages":"corrigé p. 1–3","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-social-bricopro-groupe"},"scenario":"BRICOPRO FRANCE (SBF), qui emploie 341 salariés, appartient à un groupe. La société MBI met à sa disposition une vingtaine d’informaticiens et les facture, selon les éléments du corrigé, « à prix coûtant ». MBI exerce par ailleurs une forte influence économique sur SBF : certains dirigeants sont liés au groupe, SBF dépend économiquement de MBI et des décisions d’investissement, d’approvisionnement ou de périmètre d’activité sont fortement orientées par MBI. Il faut apprécier les risques de prêt illicite de main-d’œuvre, de marchandage, puis de coemploi ou de co-subordination.","questions":[{"id":"dp-social-bricopro-groupe-01","phase":"Qualification","type":"single","stem":"Le prêt illicite de main-d’œuvre de l’article L. 8241-1 suppose notamment…","options":["une opération à but lucratif ayant pour objet exclusif le prêt de main-d’œuvre","toute mise à disposition de salariés, même gratuite","uniquement un préjudice aux salariés","un accord collectif de groupe"],"answers":[0],"explanation":"Le texte interdit l’opération à but lucratif ayant pour objet exclusif le prêt de main-d’œuvre, sous réserve des exceptions légales.","reasoning":"Séparer l’objet exclusif du prêt et son caractère lucratif.","legalRefs":["C. trav., art. L. 8241-1"],"verified":{"label":"Article L. 8241-1 vérifié sur Légifrance, version en vigueur en 2026.","url":"https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000030442435/2026-05-08"},"source":{"label":"Objectif Barreau — Droit social, corrigé sujet n°1 (Étudiants) 2026","pages":"corrigé p. 1–3","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-social-bricopro-groupe"}},{"id":"dp-social-bricopro-groupe-02","phase":"Application","type":"single","stem":"La facturation « à prix coûtant » exclut-elle en principe le but lucratif si elle se limite exactement aux éléments légaux ?","options":["Oui, si elle ne couvre que salaires, charges sociales et frais professionnels remboursés","Non, toute facturation est lucrative","Oui, même si une marge commerciale est ajoutée","Non, sauf si les salariés sont cadres"],"answers":[0],"explanation":"L’article L. 8241-1 précise qu’une opération n’est pas lucrative lorsque l’entreprise prêteuse ne facture que les salaires, charges sociales et frais professionnels remboursés.","reasoning":"Vérifier la composition réelle de la facture, pas seulement son étiquette « prix coûtant ».","legalRefs":["C. trav., art. L. 8241-1"],"verified":{"label":"Définition du prêt non lucratif vérifiée sur Légifrance.","url":"https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000030442435/2026-05-08"},"source":{"label":"Objectif Barreau — Droit social, corrigé sujet n°1 (Étudiants) 2026","pages":"corrigé p. 1–3","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-social-bricopro-groupe"}},{"id":"dp-social-bricopro-groupe-03","phase":"Règle","type":"single","stem":"Le marchandage suppose, en plus d’une opération à but lucratif de fourniture de main-d’œuvre…","options":["un préjudice au salarié concerné ou l’élusion de dispositions légales/collectives","une rémunération supérieure au SMIC","une durée de mise à disposition supérieure à six mois","la perte totale d’autonomie d’une filiale"],"answers":[0],"explanation":"C’est la définition de l’article L. 8231-1.","reasoning":"Ne pas fusionner prêt illicite et marchandage : leurs éléments constitutifs ne sont pas identiques.","legalRefs":["C. trav., art. L. 8231-1"],"verified":{"label":"Article L. 8231-1 vérifié sur Légifrance.","url":"https://www.legifrance.gouv.fr/codes/section_lc/LEGITEXT000006072050/LEGISCTA000006178271/"},"source":{"label":"Objectif Barreau — Droit social, corrigé sujet n°1 (Étudiants) 2026","pages":"corrigé p. 1–3","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-social-bricopro-groupe"}},{"id":"dp-social-bricopro-groupe-04","phase":"Conclusion","type":"single","stem":"Au vu des éléments exposés dans le corrigé, les délits de prêt illicite et de marchandage sont-ils certains ?","options":["Oui, automatiquement","Non : le caractère lucratif n’est pas précisément caractérisé, l’objet exclusif demeure incertain et aucun préjudice précis n’est identifié","Oui, car vingt salariés sont concernés","Non, car ces délits n’existent qu’en droit pénal général"],"answers":[1],"explanation":"Le corrigé conclut qu’ils ne peuvent pas être caractérisés avec certitude sur les seules informations fournies.","reasoning":"Éviter le raisonnement automatique : vérifier chaque élément constitutif.","legalRefs":["C. trav., art. L. 8231-1","C. trav., art. L. 8241-1"],"verified":null,"source":{"label":"Objectif Barreau — Droit social, corrigé sujet n°1 (Étudiants) 2026","pages":"corrigé p. 1–3","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-social-bricopro-groupe"}},{"id":"dp-social-bricopro-groupe-05","phase":"Règle","type":"single","stem":"Depuis l’arrêt du 25 novembre 2020, hors lien de subordination direct, le coemploi dans un groupe suppose…","options":["une simple domination économique","une immixtion permanente dans la gestion économique et sociale conduisant à la perte totale d’autonomie d’action de la société employeur","un dirigeant commun","un client unique"],"answers":[1],"explanation":"La Cour de cassation exige une immixtion permanente conduisant à la perte totale d’autonomie ; la coordination ou la domination économique ne suffisent pas.","reasoning":"Rechercher les deux niveaux cumulatifs : immixtion permanente + perte totale d’autonomie.","legalRefs":["Cass. soc., 25 nov. 2020, n° 18-13.769"],"verified":{"label":"Critère du coemploi vérifié sur le site de la Cour de cassation.","url":"https://www.courdecassation.fr/decision/5fca262d4504b03b8a33c16f"},"source":{"label":"Objectif Barreau — Droit social, corrigé sujet n°1 (Étudiants) 2026","pages":"corrigé p. 1–3","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-social-bricopro-groupe"}},{"id":"dp-social-bricopro-groupe-06","phase":"Conclusion","type":"single","stem":"Quelle conclusion le corrigé tire-t-il sur le coemploi et la co-subordination ?","options":["Ils sont automatiquement établis dans tout groupe","Ils paraissent peu probables : l’influence économique ne démontre pas une perte totale d’autonomie, et les faits ne caractérisent pas assez un pouvoir de subordination individualisé de l’autre société","Le coemploi est certain mais pas la co-subordination","La co-subordination est certaine dès qu’il existe une mise à disposition"],"answers":[1],"explanation":"Le corrigé refuse de déduire coemploi ou co-subordination de la seule dépendance économique et des liens de groupe.","reasoning":"Distinguer le critère institutionnel très exigeant du coemploi du lien de subordination qui doit être prouvé pour chaque travailleur.","legalRefs":["Cass. soc., 25 nov. 2020, n° 18-13.769","Cass. soc., 4 juin 2025, n° 23-17.839"],"verified":null,"source":{"label":"Objectif Barreau — Droit social, corrigé sujet n°1 (Étudiants) 2026","pages":"corrigé p. 1–3","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-social-bricopro-groupe"}}],"tags":["prêt de main-d’œuvre","marchandage","coemploi","cosubordination"],"warning":"Le sujet original BRICOPRO n’a pas été transmis séparément. L’énoncé affiché est une synthèse strictement tirée des faits reproduits dans le corrigé fourni.","status":"ready"},{"id":"dp-social-bricopro-clemence","title":"BRICOPRO — Promotion, période probatoire et licenciement","subject":"Droit social","topic":"Modification du contrat et licenciement","provider":"Objectif Barreau","year":2026,"source":{"label":"Objectif Barreau — Droit social, corrigé sujet n°1 (Étudiants) 2026","pages":"corrigé p. 4–5","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-social-bricopro-clemence"},"scenario":"Clémence travaille en CDI chez SBF depuis quinze ans. Promue de vendeuse à responsable des ventes, elle signe un avenant prévoyant une période dite « d’essai » de trois mois destinée à vérifier son aptitude aux nouvelles fonctions. Le 12 juin, l’employeur rompt immédiatement le contrat par lettre recommandée sans énoncer de motif. Après la rupture, la directrice envoie à tout le personnel un message très dépréciatif sur les compétences, la légèreté et le sérieux de Clémence.","questions":[{"id":"dp-social-bricopro-clemence-01","phase":"Qualification","type":"single","stem":"La période stipulée à l’occasion d’un changement de fonctions en cours du même contrat est juridiquement…","options":["une nouvelle période d’essai","une période probatoire","un CDD d’essai","une mise à pied"],"answers":[1],"explanation":"Le corrigé qualifie cette période de période probatoire, et non de période d’essai, puisque la relation de travail existe déjà entre les mêmes parties.","reasoning":"Qualifier la période d’abord : la sanction de sa rupture en dépend.","legalRefs":["Cass. soc., 30 mars 2005","Cass. soc., 16 mai 2012, n° 10-24.308"],"verified":null,"source":{"label":"Objectif Barreau — Droit social, corrigé sujet n°1 (Étudiants) 2026","pages":"corrigé p. 4–5","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-social-bricopro-clemence"}},{"id":"dp-social-bricopro-clemence-02","phase":"Règle","type":"single","stem":"L’insertion d’une période probatoire lors d’une affectation modifiant le contrat requiert-elle l’accord du salarié ?","options":["Non, jamais","Oui, le corrigé retient l’exigence d’un accord exprès","Oui, mais seulement pour un cadre","Non, une note de service suffit"],"answers":[1],"explanation":"Le corrigé cite la jurisprudence exigeant l’accord exprès du salarié.","reasoning":"La période probatoire peut encadrer une promotion, mais elle ne peut être imposée lorsqu’elle accompagne une modification contractuelle.","legalRefs":["Cass. soc., 16 mai 2012, n° 10-24.308"],"verified":null,"source":{"label":"Objectif Barreau — Droit social, corrigé sujet n°1 (Étudiants) 2026","pages":"corrigé p. 4–5","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-social-bricopro-clemence"}},{"id":"dp-social-bricopro-clemence-03","phase":"Application","type":"single","stem":"L’employeur peut-il traiter l’échec de la période probatoire comme une simple rupture de période d’essai mettant fin au CDI ?","options":["Oui, l’avenant l’appelle « période d’essai »","Non : le corrigé analyse la rupture du contrat comme un licenciement","Oui, si elle dure moins de trois mois","Oui, sans lettre"],"answers":[1],"explanation":"La qualification donnée par les parties ne transforme pas une période probatoire en période d’essai. La rupture de l’ensemble du CDI doit donc respecter le droit du licenciement.","reasoning":"Ne pas confondre fin de la période probatoire et rupture de la relation de travail.","legalRefs":["C. trav., art. L. 1231-1"],"verified":null,"source":{"label":"Objectif Barreau — Droit social, corrigé sujet n°1 (Étudiants) 2026","pages":"corrigé p. 4–5","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-social-bricopro-clemence"}},{"id":"dp-social-bricopro-clemence-04","phase":"Conclusion","type":"single","stem":"Aucun motif n’étant énoncé dans la lettre, quelle conclusion retient le corrigé ?","options":["Le licenciement est nécessairement justifié par la promotion ratée","Le licenciement est dépourvu de cause réelle et sérieuse","La rupture est une démission","La lettre peut être motivée oralement après le procès sans difficulté"],"answers":[1],"explanation":"Le corrigé conclut à l’absence de cause réelle et sérieuse en l’absence de motif dans la lettre de rupture.","reasoning":"Une fois la rupture qualifiée de licenciement, appliquer ses exigences propres au lieu des règles de l’essai.","legalRefs":["C. trav., art. L. 1235-3"],"verified":null,"source":{"label":"Objectif Barreau — Droit social, corrigé sujet n°1 (Étudiants) 2026","pages":"corrigé p. 4–5","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-social-bricopro-clemence"}},{"id":"dp-social-bricopro-clemence-05","phase":"Application","type":"single","stem":"Le mail collectif dénigrant Clémence après la rupture peut-il ouvrir un préjudice distinct ?","options":["Non, jamais","Oui, le corrigé envisage une responsabilité extracontractuelle pour circonstances vexatoires si un préjudice distinct est établi","Oui, automatiquement sans préjudice","Non, car le contrat est déjà rompu"],"answers":[1],"explanation":"Le corrigé rattache les propos portant atteinte à sa réputation aux circonstances vexatoires du licenciement et à un préjudice distinct.","reasoning":"Distinguer le préjudice né de l’absence de cause réelle et sérieuse de celui causé par le comportement vexatoire autonome.","legalRefs":["C. civ., art. 1240","Cass. soc., 12 mars 1987"],"verified":null,"source":{"label":"Objectif Barreau — Droit social, corrigé sujet n°1 (Étudiants) 2026","pages":"corrigé p. 4–5","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-social-bricopro-clemence"}},{"id":"dp-social-bricopro-clemence-06","phase":"Conclusion","type":"single","stem":"Pour 15 ans d’ancienneté dans une entreprise de plus de 11 salariés, quelle fourchette le corrigé indique-t-il au titre du barème L. 1235-3 ?","options":["1 à 5 mois","2 à 10 mois","3 à 13 mois bruts","6 à 18 mois nets"],"answers":[2],"explanation":"Le corrigé indique une fourchette de trois à treize mois bruts, en plus des autres indemnités éventuellement dues.","reasoning":"Ne mobiliser un barème qu’après avoir fixé ancienneté et effectif pertinents.","legalRefs":["C. trav., art. L. 1235-3"],"verified":null,"source":{"label":"Objectif Barreau — Droit social, corrigé sujet n°1 (Étudiants) 2026","pages":"corrigé p. 4–5","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-social-bricopro-clemence"}}],"tags":["période probatoire","licenciement","circonstances vexatoires"],"warning":"Le sujet original BRICOPRO n’a pas été transmis séparément. L’énoncé affiché est une synthèse strictement tirée du corrigé fourni.","status":"ready"},{"id":"dp-social-bricopro-clauses","title":"BRICOPRO — Trois clauses à ne pas rédiger n’importe comment","subject":"Droit social","topic":"Clauses du contrat de travail","provider":"Objectif Barreau","year":2026,"source":{"label":"Objectif Barreau — Droit social, corrigé sujet n°1 (Étudiants) 2026","pages":"corrigé p. 5–7","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-social-bricopro-clauses"},"scenario":"La directrice de SBF souhaite insérer plusieurs clauses : (1) une clause d’objectifs prévoyant 150 000 € de chiffre d’affaires annuel et annonçant qu’un licenciement suivra automatiquement en cas de non-atteinte ; (2) une clause de mobilité couvrant le Languedoc-Roussillon et toute autre région dans laquelle l’entreprise développera une clientèle ; (3) une clause par laquelle les salariés du conditionnement accepteraient à l’avance de travailler de nuit « en fonction des besoins du service ».","questions":[{"id":"dp-social-bricopro-clauses-01","phase":"Règle","type":"single","stem":"Une clause d’objectifs peut-elle décider à l’avance que toute non-atteinte entraînera nécessairement un licenciement justifié ?","options":["Oui, si le salarié a signé","Non, le juge conserve son pouvoir d’apprécier la cause réelle et sérieuse","Oui, si l’objectif est chiffré","Oui, uniquement pour les commerciaux"],"answers":[1],"explanation":"Le corrigé rappelle que l’insuffisance de résultats ne constitue pas en elle-même une cause automatique de rupture.","reasoning":"Une clause ne peut neutraliser le contrôle du juge sur le licenciement.","legalRefs":["Cass. soc., 3 févr. 1999","Cass. soc., 3 avr. 2001"],"verified":null,"source":{"label":"Objectif Barreau — Droit social, corrigé sujet n°1 (Étudiants) 2026","pages":"corrigé p. 5–7","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-social-bricopro-clauses"}},{"id":"dp-social-bricopro-clauses-02","phase":"Application","type":"single","stem":"Pour qu’une insuffisance de résultats puisse contribuer à justifier un licenciement, le corrigé invite notamment à vérifier…","options":["que les objectifs sont raisonnables/atteignables et que l’insuffisance est imputable à une faute ou insuffisance professionnelle","uniquement que le chiffre est écrit dans le contrat","que le salarié a moins de cinq ans d’ancienneté","que les objectifs soient fixés par le CSE"],"answers":[0],"explanation":"Le contrôle porte sur la réalité et la raisonnabilité des objectifs ainsi que sur l’imputabilité de leur non-atteinte.","reasoning":"Traiter l’objectif comme un élément du dossier, pas comme une clause de licenciement automatique.","legalRefs":["Cass. soc., 3 avr. 2001"],"verified":null,"source":{"label":"Objectif Barreau — Droit social, corrigé sujet n°1 (Étudiants) 2026","pages":"corrigé p. 5–7","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-social-bricopro-clauses"}},{"id":"dp-social-bricopro-clauses-03","phase":"Règle","type":"single","stem":"Une clause de mobilité valable doit notamment…","options":["définir précisément sa zone géographique et ne pas permettre à l’employeur de l’étendre unilatéralement","viser « tous lieux futurs »","être uniquement orale","être illimitée dans l’espace"],"answers":[0],"explanation":"Le corrigé retient ces deux exigences jurisprudentielles.","reasoning":"Repérer toute clause « évolutive » dont le périmètre dépend des choix futurs de l’employeur.","legalRefs":["Cass. soc., 7 juin 2006, n° 04-45.846"],"verified":null,"source":{"label":"Objectif Barreau — Droit social, corrigé sujet n°1 (Étudiants) 2026","pages":"corrigé p. 5–7","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-social-bricopro-clauses"}},{"id":"dp-social-bricopro-clauses-04","phase":"Application","type":"single","stem":"La clause « Languedoc-Roussillon et toute autre région dans laquelle l’entreprise développera une clientèle » est-elle valable selon le corrigé ?","options":["Oui, car la première région est précise","Non, car son périmètre est évolutif et peut être étendu unilatéralement","Oui, si le salarié est commercial","Non, uniquement parce que le Languedoc-Roussillon n’existe plus administrativement"],"answers":[1],"explanation":"Le corrigé la juge nulle en raison de son caractère évolutif : les futurs choix de développement de clientèle étendraient le champ de la mobilité.","reasoning":"La précision initiale ne sauve pas une extension future laissée à la volonté de l’employeur.","legalRefs":["Cass. soc., 17 mars 2010, n° 08-43.368","Cass. soc., 13 mai 2015, n° 14-12.698"],"verified":null,"source":{"label":"Objectif Barreau — Droit social, corrigé sujet n°1 (Étudiants) 2026","pages":"corrigé p. 5–7","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-social-bricopro-clauses"}},{"id":"dp-social-bricopro-clauses-05","phase":"Règle","type":"single","stem":"Une clause peut-elle permettre à l’employeur de modifier unilatéralement un élément du contrat selon sa seule volonté ?","options":["Oui, dès qu’elle est écrite","Non, une clause de variabilité ne peut abandonner la modification contractuelle à la volonté arbitraire de l’employeur","Oui, pour le travail de nuit","Oui, si l’entreprise compte plus de 300 salariés"],"answers":[1],"explanation":"Le corrigé rappelle l’intangibilité du contrat et le contrôle des clauses potestatives.","reasoning":"Chercher des critères objectifs de déclenchement et l’étendue exacte de ce qui est accepté.","legalRefs":["C. trav., art. L. 1121-1","C. civ., art. 1193"],"verified":null,"source":{"label":"Objectif Barreau — Droit social, corrigé sujet n°1 (Étudiants) 2026","pages":"corrigé p. 5–7","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-social-bricopro-clauses"}},{"id":"dp-social-bricopro-clauses-06","phase":"Conclusion","type":"single","stem":"La clause autorisant le travail de nuit « en fonction des besoins du service », sans critère plus précis, est-elle admise dans le corrigé ?","options":["Oui","Non, elle est considérée comme potestative et doit être encadrée par des critères objectifs","Oui, si le salarié ne proteste pas dans les 48 heures","Non, car tout travail de nuit est interdit"],"answers":[1],"explanation":"Le corrigé la considère nulle telle que rédigée et recommande des critères objectifs.","reasoning":"Une formule très générale de type « besoins du service » ne doit pas servir à renoncer par avance à une protection contractuelle.","legalRefs":["Cass. soc., 14 nov. 2018, n° 17-11.757"],"verified":null,"source":{"label":"Objectif Barreau — Droit social, corrigé sujet n°1 (Étudiants) 2026","pages":"corrigé p. 5–7","kind":"correction-2026","provider":"Objectif Barreau","caseId":"dp-social-bricopro-clauses"}}],"tags":["objectifs","mobilité","horaires","travail de nuit"],"warning":"Le sujet original BRICOPRO n’a pas été transmis séparément. L’énoncé affiché est une synthèse strictement tirée du corrigé fourni.","status":"ready"},{"id":"source-social-nutrisport","title":"NUTRISPORT — Sujet social n°2","subject":"Droit social","topic":"Période d’essai · vie personnelle · heures supplémentaires · accords collectifs","provider":"Objectif Barreau","year":2026,"source":{"label":"Objectif Barreau — Droit social, sujet n°2 2026","pages":"sujet p. 1–2","kind":"subject-only","provider":"Objectif Barreau","caseId":"source-social-nutrisport"},"scenario":"NUTRISPORT (293 salariés, groupe MULTISPORT) sollicite des conseils sur quatre ensembles de difficultés : (1) la rupture, le 25 novembre 2025, de la période d’essai de Bertrand pour perte du client auquel il était affecté, avec un délai de prévenance annoncé jusqu’au 9 décembre alors que le terme de l’essai était fixé au 30 novembre ; (2) le licenciement pour faute grave de Pierre après des messages insistants adressés à une ancienne partenaire de travail et le projet de demander aux dirigeants de révéler leurs relations intimes ou amicales avec des salariés ; (3) la preuve d’heures supplémentaires réclamées par Jean-Paul alors que l’employeur reconnaît ne disposer d’aucun système de contrôle du temps de travail ; (4) l’articulation d’un futur accord d’entreprise avec un minimum salarial de branche et avec des congés supplémentaires prévus au niveau du groupe ou dans certains contrats individuels.","questions":[],"tags":["sujet seul","en attente du corrigé"],"warning":"Corrigé non fourni : aucune solution n’a été inventée. Le sujet est importé et prêt à être transformé dès réception du corrigé.","status":"source_only"},{"id":"source-social-nero","title":"NERO — Accident du travail, inaptitude et mobilité","subject":"Droit social","topic":"AT/MP · faute inexcusable · indemnités · mobilité","provider":"Pré-Barreau","year":2026,"source":{"label":"Pré-Barreau — Droit social, épreuve n°4 2026","pages":"sujet p. 1","kind":"subject-only","provider":"Pré-Barreau","caseId":"source-social-nero"},"scenario":"La société NERO interroge son conseil sur trois consultations : (1) Monsieur Romantik, mécanicien à temps partiel, a subi un grave accident reconnu professionnel alors qu’une restriction médicale lui interdisait de porter plus de 5 kg ; l’employeur découvre ensuite qu’il réparait le véhicule d’un ami au moment de l’accident et veut discuter le caractère professionnel, la prescription et la faute inexcusable ; (2) l’entreprise envisage un licenciement pour inaptitude et un protocole transactionnel et veut connaître le régime social des indemnités ; (3) elle hésite entre un véhicule de fonction électrique utilisable à titre privé et un forfait mobilités durables pour limiter les cotisations sociales.","questions":[],"tags":["sujet seul","en attente du corrigé"],"warning":"Corrigé non fourni : aucune solution n’a été inventée. Le sujet est importé et prêt à être transformé dès réception du corrigé.","status":"source_only"}];
